async fn create_dynamic_workflow_plan(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<CreateDynamicWorkflowPlan>,
) -> Result<Json<DynamicWorkflowPlan>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::SessionsWrite,
        "dynamic_workflow_plans",
        None,
    )
    .await?;
    if let Some(work_item_id) = input.source_work_item_id {
        authorize_request(
            &state,
            &headers,
            Permission::SessionsRead,
            "work_item",
            Some(work_item_id),
        )
        .await?;
    }
    if let Some(session_id) = input.source_session_id {
        authorize_request(
            &state,
            &headers,
            Permission::SessionsRead,
            "session",
            Some(session_id),
        )
        .await?;
        state.get_session(session_id).await?;
    }
    let objective = require_non_empty(input.objective, "dynamic workflow objective")?;
    let phases = validate_dynamic_workflow_phases(input.phases)?;
    let agent_fleet_policy =
        validate_dynamic_workflow_agent_fleet_policy(input.agent_fleet_policy)?;
    let governance = validate_dynamic_workflow_governance(input.governance)?;
    let validation = validate_dynamic_workflow_validation(input.validation)?;
    let materialization = validate_dynamic_workflow_materialization(input.materialization)?;
    let analysis = analyze_dynamic_workflow_plan(
        &phases,
        &agent_fleet_policy,
        &governance,
        &validation,
        &materialization,
    )?;
    let now = Utc::now();
    let plan = state
        .create_dynamic_workflow_plan(DynamicWorkflowPlan {
            id: Uuid::new_v4(),
            source_work_item_id: input.source_work_item_id,
            source_session_id: input.source_session_id,
            objective,
            status: "proposed".to_string(),
            phases,
            agent_fleet_policy,
            governance,
            validation,
            materialization,
            analysis,
            review: empty_json_object(),
            workflow_definition_id: None,
            workflow_run_id: None,
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
            reviewed_at: None,
            materialized_at: None,
        })
        .await?;
    let audit = record_dynamic_workflow_plan_audit(
        &state,
        &plan,
        "dynamic_workflow_plan.created",
        json!({"status": plan.status, "analysis": plan.analysis}),
    )
    .await?;
    let plan = state
        .update_dynamic_workflow_plan_audit_trace(plan.id, Some(audit.id), audit.created_at)
        .await?;
    Ok(Json(plan))
}

async fn compile_dynamic_workflow_plan(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<CompileDynamicWorkflowPlan>,
) -> Result<Json<DynamicWorkflowPlanCompilationResponse>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::SessionsWrite,
        "dynamic_workflow_plans",
        None,
    )
    .await?;
    if let Some(work_item_id) = input.source_work_item_id {
        authorize_request(
            &state,
            &headers,
            Permission::SessionsRead,
            "work_item",
            Some(work_item_id),
        )
        .await?;
    }
    if let Some(session_id) = input.source_session_id {
        authorize_request(
            &state,
            &headers,
            Permission::SessionsRead,
            "session",
            Some(session_id),
        )
        .await?;
        state.get_session(session_id).await?;
    }
    let objective = require_non_empty(input.objective, "dynamic workflow objective")?;
    let max_total_agents = input.max_total_agents.unwrap_or(8).clamp(1, 1000);
    let max_parallel_agents = input
        .max_parallel_agents
        .unwrap_or(4)
        .clamp(1, 16)
        .min(max_total_agents);
    let runtime_adapter = input
        .runtime_adapter
        .and_then(normalize_optional_text)
        .unwrap_or_else(|| "codex_app_server".to_string());
    let runtime_adapter = normalize_optional_runtime_adapter(Some(runtime_adapter))?
        .unwrap_or_else(|| "codex_app_server".to_string());
    let execution_strategy = input
        .execution_strategy
        .and_then(normalize_optional_text)
        .unwrap_or_else(|| "native_dynamic".to_string());
    let execution_strategy = normalize_workflow_execution_strategy(&execution_strategy)?;
    let phases = if execution_strategy == "native_dynamic" {
        compile_native_dynamic_workflow_phases(&objective, max_total_agents, max_parallel_agents)
    } else {
        compile_dynamic_workflow_phases(&objective, max_total_agents, max_parallel_agents)
    };
    let request = CreateDynamicWorkflowPlan {
        source_work_item_id: input.source_work_item_id,
        source_session_id: input.source_session_id,
        objective: objective.clone(),
        phases: phases.clone(),
        agent_fleet_policy: json!({
            "max_total_agents": max_total_agents,
            "max_parallel_agents": max_parallel_agents,
            "timeout_seconds": 3600,
            "retry_limit": 1
        }),
        governance: json!({
            "risk_level": "medium",
            "memory_scope": {"read": ["session"], "write": ["session"]},
            "tool_scope": {"allowed_tools": ["file.read", "artifact.create"]},
            "connector_scope": {"allowed_connectors": []},
            "approval_policy": {"required_for": ["external_commit"]},
            "external_effects": {"mode": "draft_only"}
        }),
        validation: json!({
            "cross_check_required": true,
            "vote_threshold": 0.67,
            "required_artifacts": ["final_report"],
            "adjudication": "majority_vote_with_synthesis"
        }),
        materialization: json!({
            "execution_strategy": execution_strategy,
            "runtime_adapter": runtime_adapter,
            "runtime_mode": "dynamic_workflow",
            "runtime_capability_contract": {
                "max_total_agents": max_total_agents,
                "max_parallel_agents": max_parallel_agents,
                "allowed_tools": ["file.read", "artifact.create"]
            },
            "event_ingestion_policy": "normalized"
        }),
    };
    let analysis = analyze_dynamic_workflow_plan(
        &request.phases,
        &request.agent_fleet_policy,
        &request.governance,
        &request.validation,
        &request.materialization,
    )?;
    Ok(Json(DynamicWorkflowPlanCompilationResponse {
        request,
        compiler: json!({
            "name": "mandoforge-rule-compiler-v1",
            "status": "compiled",
            "analysis": analysis,
            "notes": [
                "deterministic compiler generated reviewable dynamic workflow phases from objective",
                "materialization still requires plan creation and approval"
            ]
        }),
    }))
}

async fn review_dynamic_workflow_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<ReviewDynamicWorkflowPlan>,
) -> Result<Json<DynamicWorkflowPlan>, AppError> {
    let current = state.get_dynamic_workflow_plan(id).await?;
    authorize_dynamic_workflow_plan_run(&state, &headers, &current).await?;
    if !input.review.is_object() {
        return Err(AppError::bad_request(
            "dynamic workflow plan review must be a JSON object",
        ));
    }
    let status = match input.status {
        Some(status) => normalize_dynamic_workflow_plan_status(&status)?,
        None => "reviewed".to_string(),
    };
    if current.status == "materialized" {
        return Err(AppError::bad_request(
            "materialized dynamic workflow plan cannot be reviewed",
        ));
    }
    let reviewed_at = Utc::now();
    let reviewed = state
        .update_dynamic_workflow_plan_review(
            current.id,
            status,
            input.review,
            current.audit_trace_id,
            reviewed_at,
        )
        .await?;
    let audit = record_dynamic_workflow_plan_audit(
        &state,
        &reviewed,
        "dynamic_workflow_plan.reviewed",
        json!({"status": reviewed.status, "review": reviewed.review}),
    )
    .await?;
    let reviewed = state
        .update_dynamic_workflow_plan_review(
            reviewed.id,
            reviewed.status.clone(),
            reviewed.review.clone(),
            Some(audit.id),
            reviewed_at,
        )
        .await?;
    Ok(Json(reviewed))
}

async fn adjudicate_dynamic_workflow_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<DynamicWorkflowAdjudicationRequest>,
) -> Result<Json<DynamicWorkflowAdjudicationResponse>, AppError> {
    let plan = state.get_dynamic_workflow_plan(id).await?;
    authorize_dynamic_workflow_plan_run(&state, &headers, &plan).await?;
    let workflow_run_id = plan.workflow_run_id.ok_or_else(|| {
        AppError::bad_request("dynamic workflow plan must be materialized before adjudication")
    })?;
    let run = state.get_workflow_run(workflow_run_id).await?;
    let threshold = input
        .vote_threshold
        .or_else(|| {
            plan.validation
                .get("vote_threshold")
                .and_then(Value::as_f64)
        })
        .unwrap_or(0.67);
    if !(0.0..=1.0).contains(&threshold) {
        return Err(AppError::bad_request(
            "dynamic workflow adjudication threshold must be between 0 and 1",
        ));
    }
    let steps = state.list_workflow_step_runs(run.id).await?;
    let completed = steps
        .iter()
        .filter(|step| step.status == "completed")
        .collect::<Vec<_>>();
    let explicit_votes = completed
        .iter()
        .filter_map(|step| dynamic_workflow_step_vote(&step.output_payload))
        .collect::<Vec<_>>();
    let positive_votes = explicit_votes.iter().filter(|vote| **vote).count();
    let negative_votes = explicit_votes.len().saturating_sub(positive_votes);
    let missing_votes = completed.len().saturating_sub(explicit_votes.len());
    let score = if explicit_votes.is_empty() {
        0.0
    } else {
        positive_votes as f64 / explicit_votes.len() as f64
    };
    let decision = if explicit_votes.is_empty() || missing_votes > 0 {
        "insufficient_evidence"
    } else if score >= threshold {
        "accepted"
    } else {
        "needs_review"
    }
    .to_string();
    let response = DynamicWorkflowAdjudicationResponse {
        status: "completed".to_string(),
        plan_id: plan.id,
        workflow_run_id: run.id,
        threshold,
        completed_votes: completed.len(),
        positive_votes,
        negative_votes,
        score,
        decision,
        evidence: json!({
            "step_count": steps.len(),
            "completed_step_ids": completed.iter().map(|step| step.id).collect::<Vec<_>>(),
            "explicit_vote_count": explicit_votes.len(),
            "missing_vote_count": missing_votes,
            "validation": plan.validation,
            "cross_check_required": plan.validation.get("cross_check_required").and_then(Value::as_bool).unwrap_or(false)
        }),
    };
    state
        .append_event(
            "system",
            Some(run.id),
            run.primary_session_id,
            "dynamic_workflow.adjudicated",
            serde_json::to_value(&response)?,
        )
        .await?;
    state
        .append_audit_log(new_audit_log(
            Some(run.primary_session_id),
            "system",
            Some(run.id),
            "dynamic_workflow.adjudicated",
            "dynamic_workflow_plan",
            Some(plan.id),
            serde_json::to_value(&response)?,
        ))
        .await?;
    Ok(Json(response))
}

async fn pressure_test_dynamic_workflow_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<DynamicWorkflowPressureTestRequest>,
) -> Result<Json<DynamicWorkflowPressureTestResponse>, AppError> {
    let plan = state.get_dynamic_workflow_plan(id).await?;
    authorize_dynamic_workflow_plan_run(&state, &headers, &plan).await?;
    let max_total = dynamic_policy_u64(&plan.agent_fleet_policy, "max_total_agents", 64)?;
    let policy_parallel =
        dynamic_policy_u64(&plan.agent_fleet_policy, "max_parallel_agents", 16)?.clamp(1, 16);
    let target_agents = input.target_agents.unwrap_or(max_total).clamp(1, 1000);
    if target_agents > max_total {
        return Err(AppError::bad_request(format!(
            "dynamic workflow pressure target {target_agents} exceeds plan max_total_agents {max_total}"
        )));
    }
    let max_parallel_agents = input
        .max_parallel_agents
        .unwrap_or(policy_parallel)
        .clamp(1, 16)
        .min(target_agents);
    let simulated_batches = target_agents.div_ceil(max_parallel_agents);
    let response = DynamicWorkflowPressureTestResponse {
        status: "control_plane_passed".to_string(),
        plan_id: plan.id,
        target_agents,
        max_parallel_agents,
        simulated_batches,
        estimated_worker_claims: target_agents,
        evidence: json!({
            "type": "control_plane_pressure_simulation",
            "policy_max_total_agents": max_total,
            "policy_max_parallel_agents": policy_parallel,
            "claim_backpressure": "max_parallel_agents",
            "note": "This proves planning/backpressure math, not live LLM execution cost or provider capacity."
        }),
    };
    state
        .append_audit_log(new_audit_log(
            None,
            "system",
            Some(plan.id),
            "dynamic_workflow.pressure_tested",
            "dynamic_workflow_plan",
            Some(plan.id),
            serde_json::to_value(&response)?,
        ))
        .await?;
    Ok(Json(response))
}

async fn materialize_dynamic_workflow_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<MaterializeDynamicWorkflowPlan>,
) -> Result<Json<DynamicWorkflowPlanMaterializationResponse>, AppError> {
    let plan = state.get_dynamic_workflow_plan(id).await?;
    authorize_dynamic_workflow_plan_run(&state, &headers, &plan).await?;
    if plan.status != "approved" {
        return Err(AppError::bad_request(
            "dynamic workflow plan must be approved before materialization",
        ));
    }
    let agent = workflow_pack_materialization_default_agent(&state).await?;
    let execution_strategy = dynamic_workflow_plan_execution_strategy(&plan)?;
    let runtime_adapter = dynamic_workflow_plan_runtime_adapter(&plan)?;
    let runtime_mode = dynamic_workflow_plan_runtime_mode(&plan)?;
    let runtime_capability_contract = dynamic_workflow_plan_runtime_capability_contract(&plan)?;
    let event_ingestion_policy = dynamic_workflow_plan_event_ingestion_policy(&plan)?;
    validate_workflow_execution_binding(
        &execution_strategy,
        runtime_adapter.as_deref(),
        &runtime_capability_contract,
    )?;
    let step_graph = dynamic_workflow_plan_step_graph(&plan, &execution_strategy)?;
    validate_workflow_graph_definition(&step_graph)?;
    let now = Utc::now();
    let workflow_definition = state
        .create_workflow_definition(WorkflowDefinition {
            id: Uuid::new_v4(),
            pack_installation_id: None,
            pack_id: None,
            pack_version: None,
            name: format!("Dynamic plan: {}", plan.objective),
            entrypoint: format!("dynamic-{}", workflow_slug(&plan.objective)),
            trigger_type: "manual".to_string(),
            default_agent_id: agent.id,
            default_environment_id: input.environment_id,
            input_schema_ref: None,
            output_schema_ref: None,
            step_graph,
            handoff_rules: dynamic_workflow_plan_handoff_rules(&plan),
            execution_strategy: execution_strategy.clone(),
            runtime_adapter: runtime_adapter.clone(),
            runtime_mode: runtime_mode.clone(),
            runtime_capability_contract: runtime_capability_contract.clone(),
            event_ingestion_policy: event_ingestion_policy.clone(),
            approval_policy_ref: None,
            eval_gate_refs: Vec::new(),
            release_state: "released".to_string(),
            created_at: now,
            updated_at: now,
            archived_at: None,
        })
        .await?;
    let session = state
        .create_session(CreateSession {
            agent_id: workflow_definition.default_agent_id,
            environment_id: input.environment_id,
            title: input
                .title
                .filter(|title| !title.trim().is_empty())
                .unwrap_or_else(|| format!("Dynamic workflow: {}", plan.objective)),
            message: Some(plan.objective.clone()),
        })
        .await?;
    ensure_primary_session_thread(&state, session.id).await?;
    let input_payload = if input.input_payload.is_object()
        && !input
            .input_payload
            .as_object()
            .is_some_and(serde_json::Map::is_empty)
    {
        input.input_payload
    } else {
        json!({
            "objective": plan.objective,
            "dynamic_workflow_plan_id": plan.id,
            "phases": plan.phases
        })
    };
    let input_digest = workflow_input_digest(&input_payload);
    let runtime_envelope = workflow_run_runtime_envelope(
        &workflow_definition,
        &execution_strategy,
        runtime_adapter.as_deref(),
        runtime_mode.as_deref(),
        None,
        &json!({
            "dynamic_workflow_plan_id": plan.id,
            "objective": plan.objective,
            "phases": plan.phases,
            "agent_fleet_policy": plan.agent_fleet_policy,
            "validation": plan.validation,
            "analysis": plan.analysis
        }),
    );
    let workflow_run = state
        .create_workflow_run(WorkflowRun {
            id: Uuid::new_v4(),
            workflow_definition_id: workflow_definition.id,
            pack_installation_id: None,
            source_event_id: None,
            source_work_item_id: plan.source_work_item_id,
            source_schedule_id: None,
            status: "queued".to_string(),
            primary_session_id: session.id,
            root_task_grant_id: None,
            input_payload,
            input_digest,
            execution_strategy,
            runtime_adapter,
            runtime_mode,
            delegation_status: (workflow_definition.execution_strategy == "delegated_runtime")
                .then_some("submitted".to_string()),
            external_run_ref: None,
            runtime_event_cursor: None,
            runtime_envelope,
            started_at: None,
            completed_at: None,
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
        })
        .await?;
    let root_grant = issue_root_task_grant_for_workflow_run(
        &state,
        &workflow_run,
        &workflow_definition,
        &session,
    )
    .await?;
    let workflow_run = state
        .update_workflow_run_root_task_grant(workflow_run.id, root_grant.id)
        .await?;
    materialize_workflow_graph_start_steps(
        &state,
        &workflow_definition,
        &workflow_run,
        &session,
        &root_grant,
    )
    .await?;
    state
        .append_event(
            "system",
            Some(workflow_run.id),
            session.id,
            "dynamic_workflow_plan.materialized",
            json!({
                "dynamic_workflow_plan_id": plan.id,
                "workflow_definition_id": workflow_definition.id,
                "workflow_run_id": workflow_run.id,
                "execution_strategy": workflow_run.execution_strategy,
                "runtime_adapter": workflow_run.runtime_adapter,
                "runtime_mode": workflow_run.runtime_mode,
                "root_task_grant_id": workflow_run.root_task_grant_id
            }),
        )
        .await?;
    let audit = record_dynamic_workflow_plan_audit(
        &state,
        &plan,
        "dynamic_workflow_plan.materialized",
        json!({
            "workflow_definition_id": workflow_definition.id,
            "workflow_run_id": workflow_run.id,
            "root_task_grant_id": workflow_run.root_task_grant_id,
            "execution_strategy": workflow_run.execution_strategy,
            "runtime_adapter": workflow_run.runtime_adapter,
            "runtime_mode": workflow_run.runtime_mode
        }),
    )
    .await?;
    let plan = state
        .update_dynamic_workflow_plan_materialized(
            plan.id,
            workflow_definition.id,
            workflow_run.id,
            Some(audit.id),
            now,
        )
        .await?;
    Ok(Json(DynamicWorkflowPlanMaterializationResponse {
        plan,
        workflow_definition,
        workflow_run,
    }))
}

async fn get_capability_discovery(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<Value>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::AgentsRead,
        "capability_discovery",
        None,
    )
    .await?;
    let agents = state.list_agents().await?;
    let work_items = state.list_work_items().await?;
    let pending_memory = state
        .list_memory_writeback_candidates(None)
        .await?
        .into_iter()
        .filter(|candidate| candidate.status == "pending")
        .count();
    let agent_cards = agents
        .iter()
        .map(|agent| {
            json!({
                "agent_id": agent.id,
                "name": agent.name,
                "kind": agent.kind,
                "agent_role": agent.agent_role,
                "provider": agent.provider,
                "model": agent.model,
                "release_state": agent.release_state,
                "tools": agent.tools,
                "skill_ids": agent.skill_ids,
                "workflow_pack_ids": agent.workflow_pack_ids,
                "semantic_scopes": agent.semantic_scopes,
                "primary_action": capability_primary_action(agent),
                "failure_modes": capability_failure_modes(agent),
                "sample_tasks": capability_sample_tasks(agent),
            })
        })
        .collect::<Vec<_>>();
    Ok(Json(json!({
        "status": "ready",
        "generated_at": Utc::now(),
        "summary": {
            "agent_count": agents.len(),
            "open_work_item_count": work_items.iter().filter(|item| !matches!(item.status.as_str(), "done" | "canceled")).count(),
            "pending_memory_review_count": pending_memory,
        },
        "agent_cards": agent_cards,
        "suggested_prompts": [
            {
                "target_view": "manager",
                "title": "拆解并派发一个工作项",
                "prompt": "请把这个目标拆解成 WorkItem、选择合适 Agent、设置 SLA，并建立复审点。",
                "action": "create_work_item_then_start_pack_workflow"
            },
            {
                "target_view": "semantic",
                "title": "整理领域记忆",
                "prompt": "请扫描这个 domain 的冲突、过期记忆与 ontology 缺口，建立需要复审的队列。",
                "action": "open_semantic_workbench"
            },
            {
                "target_view": "board",
                "title": "查看队列风险",
                "prompt": "请找出 blocked、overdue、无人领取的任务，并给出下一步处理建议。",
                "action": "inspect_task_board"
            }
        ],
        "onboarding_steps": [
            {
                "key": "create_work_item",
                "title": "建立 WorkItem",
                "description": "先把业务目标变成可审计、可派工、可复审的任务。"
            },
            {
                "key": "start_pack_manager_workflow",
                "title": "启动 Pack Manager Workflow",
                "description": "通过 Workflow Pack 定义的 manager workflow 做 intake、拆解、派工、SLA 检查和复审。"
            },
            {
                "key": "review_memory",
                "title": "复审 Memory Queue",
                "description": "批准或拒绝 reflection / dreaming 产生的记忆候选。"
            },
            {
                "key": "install_pack",
                "title": "安装 Workflow Pack",
                "description": "把领域流程、Agent 技能和运行对象绑定成可复用模板。"
            }
        ],
        "empty_states": [
            {
                "view": "manager",
                "title": "还没有 Pack Manager Workflow 结果",
                "action": "start_pack_manager_workflow"
            },
            {
                "view": "semantic",
                "title": "还没有可治理的语义对象",
                "action": "ingest_semantic_source"
            },
            {
                "view": "board",
                "title": "还没有 WorkItem",
                "action": "create_work_item"
            }
        ],
    })))
}

fn capability_primary_action(agent: &Agent) -> &'static str {
    match agent.agent_role.as_str() {
        "manager" => "start_pack_manager_workflow",
        "specialist" => "claim_specialist_work",
        _ => "start_session",
    }
}

fn capability_failure_modes(agent: &Agent) -> Vec<&'static str> {
    let mut modes = vec!["missing_context", "approval_required"];
    if agent.tools.is_empty() {
        modes.push("no_tools_configured");
    }
    if agent.workflow_pack_ids.is_empty() {
        modes.push("no_workflow_pack_bound");
    }
    modes
}

fn capability_sample_tasks(agent: &Agent) -> Vec<String> {
    match agent.agent_role.as_str() {
        "manager" => vec![
            "拆解新的 WorkItem 并选择 specialist agent".to_string(),
            "巡检 blocked / overdue 队列并建立复审".to_string(),
        ],
        "specialist" => vec![
            "领取一个已派发的 WorkItem 并产出 evidence".to_string(),
            "根据 context packet 执行技能包内的步骤".to_string(),
        ],
        _ => vec!["启动一个受治理的 managed session".to_string()],
    }
}

async fn get_manager_agent_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
) -> Result<Json<ManagerAgentPlan>, AppError> {
    let plan = state.get_manager_agent_plan(id).await?;
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRead,
        "session",
        Some(plan.session_id),
    )
    .await?;
    Ok(Json(plan))
}

async fn create_manager_agent_plan(
    State(state): State<AppState>,
    Path(session_id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<CreateManagerAgentPlan>,
) -> Result<Json<ManagerAgentPlan>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "session",
        Some(session_id),
    )
    .await?;
    let session = state.get_session(session_id).await?;
    let manager_agent = state.get_agent(session.agent_id).await?;
    if manager_agent.agent_role != "manager" {
        return Err(AppError::bad_request(
            "manager agent plans require a session bound to a manager agent",
        ));
    }
    if !input.task_intake.is_object()
        || !input.decomposition.is_object()
        || !input.specialist_selection.is_object()
        || !input.review.is_object()
    {
        return Err(AppError::bad_request(
            "manager agent plan sections must be JSON objects",
        ));
    }
    let risk_classification = normalize_manager_plan_risk(&input.risk_classification)?;
    if let Some(specialist_agent_id) = input.specialist_agent_id {
        let specialist = state.get_agent(specialist_agent_id).await?;
        if specialist.agent_role != "specialist" {
            return Err(AppError::bad_request(
                "specialist_agent_id must reference a specialist agent",
            ));
        }
    }
    if let Some(work_item_id) = input.work_item_id {
        state.ensure_work_item_exists(work_item_id).await?;
    }
    let now = Utc::now();
    let plan = state
        .create_manager_agent_plan(ManagerAgentPlan {
            id: Uuid::new_v4(),
            session_id,
            manager_agent_id: manager_agent.id,
            work_item_id: input.work_item_id,
            specialist_agent_id: input.specialist_agent_id,
            task_intake: input.task_intake,
            decomposition: input.decomposition,
            specialist_selection: input.specialist_selection,
            risk_classification,
            review: input.review,
            status: "planned".to_string(),
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
        })
        .await?;
    let audit =
        record_manager_agent_plan_audit_and_event(&state, &plan, "manager_plan.created").await?;
    record_manager_agent_plan_work_item_activity(&state, &plan, "manager_plan.created").await?;
    let plan = state
        .update_manager_agent_plan_review(
            plan.id,
            plan.review.clone(),
            plan.status.clone(),
            Some(audit.id),
        )
        .await?;
    Ok(Json(plan))
}

async fn review_manager_agent_plan(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<ReviewManagerAgentPlan>,
) -> Result<Json<ManagerAgentPlan>, AppError> {
    let current = state.get_manager_agent_plan(id).await?;
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "session",
        Some(current.session_id),
    )
    .await?;
    if !input.review.is_object() {
        return Err(AppError::bad_request(
            "manager agent plan review must be a JSON object",
        ));
    }
    let status = match input.status {
        Some(status) => normalize_manager_plan_status(&status)?,
        None => "reviewed".to_string(),
    };
    let reviewed = state
        .update_manager_agent_plan_review(current.id, input.review, status, current.audit_trace_id)
        .await?;
    let audit =
        record_manager_agent_plan_audit_and_event(&state, &reviewed, "manager_plan.reviewed")
            .await?;
    record_manager_agent_plan_work_item_activity(&state, &reviewed, "manager_plan.reviewed")
        .await?;
    let reviewed = state
        .update_manager_agent_plan_review(
            reviewed.id,
            reviewed.review.clone(),
            reviewed.status.clone(),
            Some(audit.id),
        )
        .await?;
    Ok(Json(reviewed))
}

async fn create_agent_handoff_event(
    State(state): State<AppState>,
    Path(session_id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<CreateAgentHandoffEvent>,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "session",
        Some(session_id),
    )
    .await?;
    let session = state.get_session(session_id).await?;
    let source_version = state.agent_version_for_session(session_id).await?;
    let target_agent = state.get_agent(input.target_agent_id).await?;
    if target_agent.agent_role != "specialist" {
        return Err(AppError::bad_request(
            "agent handoff target must be a specialist agent",
        ));
    }
    let manager_plan = match input.manager_plan_id {
        Some(plan_id) => {
            let plan = state.get_manager_agent_plan(plan_id).await?;
            if plan.session_id != session_id {
                return Err(AppError::bad_request(
                    "manager_plan_id must belong to the source session",
                ));
            }
            if plan.manager_agent_id != session.agent_id {
                return Err(AppError::bad_request(
                    "manager_plan_id must belong to the source manager agent",
                ));
            }
            if let Some(planned_specialist_id) = plan.specialist_agent_id
                && planned_specialist_id != input.target_agent_id
            {
                return Err(AppError::bad_request(
                    "manager_plan_id specialist does not match target_agent_id",
                ));
            }
            Some(plan)
        }
        None => None,
    };
    let intent = validate_handoff_token("intent", &input.intent)?;
    let schema_version = validate_handoff_schema_version(&input.schema_version)?;
    let risk_level = normalize_handoff_risk_level(&input.risk_level)?;
    if risk_level == "high" && !input.approval_required {
        return Err(AppError::bad_request(
            "high-risk handoffs must require approval",
        ));
    }
    if !input.payload.is_object() {
        return Err(AppError::bad_request(
            "handoff payload must be a JSON object",
        ));
    }
    let rule = matching_handoff_rule(
        &source_version.runtime_config,
        input.target_agent_id,
        &intent,
        &schema_version,
        &risk_level,
        input.approval_required,
    )?;
    validate_handoff_payload_schema(&input.payload, rule.get("payload_schema"))?;
    let semantic_scopes = normalize_handoff_semantic_scopes(
        input
            .semantic_scopes
            .unwrap_or_else(|| target_agent.semantic_scopes.clone()),
    )?;
    let runtime_profile_id = input.runtime_profile_id.or(target_agent.runtime_profile_id);
    let runtime_profile = match runtime_profile_id {
        Some(profile_id) => Some(state.get_agent_runtime_profile(profile_id).await?),
        None => None,
    };
    let remote_computer_required = input.remote_computer_required.unwrap_or_else(|| {
        handoff_remote_computer_required(&target_agent, runtime_profile.as_ref())
    });
    let review_status = normalize_handoff_review_status(
        input
            .review_status
            .as_deref()
            .unwrap_or_else(|| default_handoff_review_status(manager_plan.as_ref())),
    )?;
    let human_escalation_status = normalize_handoff_human_escalation_status(
        input.human_escalation_status.as_deref().unwrap_or("none"),
    )?;

    let now = Utc::now();
    let event = state
        .create_agent_handoff_event(AgentHandoffEvent {
            id: Uuid::new_v4(),
            source_session_id: session_id,
            source_agent_id: session.agent_id,
            target_agent_id: input.target_agent_id,
            manager_plan_id: input.manager_plan_id,
            intent,
            payload: input.payload,
            schema_version,
            risk_level,
            approval_required: input.approval_required,
            semantic_scopes,
            runtime_profile_id,
            remote_computer_required,
            review_status,
            human_escalation_status,
            status: "requested".to_string(),
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
        })
        .await?;
    let audit =
        record_agent_handoff_audit_and_event(&state, &event, "agent_handoff.requested", None)
            .await?;
    let event = state
        .update_agent_handoff_event_status(event.id, "requested", Some(audit.id))
        .await?;
    Ok(Json(event))
}

async fn accept_agent_handoff_event(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<TransitionAgentHandoffEvent>,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    transition_agent_handoff_event(state, id, headers, input, "accepted").await
}

async fn reject_agent_handoff_event(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<TransitionAgentHandoffEvent>,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    transition_agent_handoff_event(state, id, headers, input, "rejected").await
}

async fn fail_agent_handoff_event(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<TransitionAgentHandoffEvent>,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    transition_agent_handoff_event(state, id, headers, input, "failed").await
}

async fn escalate_agent_handoff_event(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<EscalateAgentHandoffEvent>,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    let current = state.get_agent_handoff_event(id).await?;
    authorize_request(
        &state,
        &headers,
        Permission::ApprovalsDecide,
        "session",
        Some(current.source_session_id),
    )
    .await?;
    if matches!(current.status.as_str(), "completed" | "rejected") {
        return Err(AppError::bad_request(
            "completed or rejected handoffs cannot be escalated",
        ));
    }
    let next_status =
        normalize_handoff_human_escalation_status(input.status.as_deref().unwrap_or("requested"))?;
    if next_status == "none" {
        return Err(AppError::bad_request(
            "handoff escalation status must be required, requested, or resolved",
        ));
    }
    let audit = record_agent_handoff_audit_and_event(
        &state,
        &current,
        "agent_handoff.escalated",
        input.reason,
    )
    .await?;
    let updated = state
        .update_agent_handoff_event_escalation(current.id, &next_status, Some(audit.id))
        .await?;
    Ok(Json(updated))
}

async fn complete_agent_handoff_event(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<TransitionAgentHandoffEvent>,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    transition_agent_handoff_event(state, id, headers, input, "completed").await
}

async fn assign_agent_handoff_event(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<CreateAgentHandoffAssignment>,
) -> Result<Json<AgentHandoffAssignment>, AppError> {
    let handoff = state.get_agent_handoff_event(id).await?;
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "session",
        Some(handoff.source_session_id),
    )
    .await?;
    if handoff.status != "accepted" {
        return Err(AppError::bad_request(
            "agent handoff must be accepted before assignment",
        ));
    }
    let manager_plan_id = handoff.manager_plan_id.ok_or_else(|| {
        AppError::bad_request("agent handoff assignment requires manager_plan_id")
    })?;
    let manager_plan = state.get_manager_agent_plan(manager_plan_id).await?;
    if manager_plan.status != "approved" && manager_plan.status != "reviewed" {
        return Err(AppError::bad_request(
            "manager plan must be reviewed or approved before handoff assignment",
        ));
    }
    if manager_plan.session_id != handoff.source_session_id
        || manager_plan.manager_agent_id != handoff.source_agent_id
    {
        return Err(AppError::bad_request(
            "manager plan does not match handoff source session and agent",
        ));
    }
    if let Some(specialist_agent_id) = manager_plan.specialist_agent_id
        && specialist_agent_id != handoff.target_agent_id
    {
        return Err(AppError::bad_request(
            "manager plan specialist does not match handoff target agent",
        ));
    }
    let target_agent = state.get_agent(handoff.target_agent_id).await?;
    if target_agent.agent_role != "specialist" {
        return Err(AppError::bad_request(
            "agent handoff assignment target must be a specialist agent",
        ));
    }
    if state
        .get_agent_handoff_assignment_for_handoff(handoff.id)
        .await?
        .is_some()
    {
        return Err(AppError::bad_request(
            "agent handoff already has an assignment",
        ));
    }
    if let Some(profile_id) = handoff.runtime_profile_id {
        let profile = state.get_agent_runtime_profile(profile_id).await?;
        if profile.status != "enabled" {
            return Err(AppError::bad_request(
                "agent handoff runtime profile must be enabled",
            ));
        }
    }
    if let Some(remote_assignment_id) = input.remote_computer_job_assignment_id {
        let remote_assignment = state
            .list_remote_computer_job_assignments()
            .await?
            .into_iter()
            .find(|assignment| assignment.id == remote_assignment_id)
            .ok_or_else(|| AppError::not_found("remote computer job assignment not found"))?;
        if remote_assignment.session_id != handoff.source_session_id {
            return Err(AppError::bad_request(
                "remote computer job assignment must belong to the source session until the specialist execution job exists",
            ));
        }
    }
    let source_session = state.get_session(handoff.source_session_id).await?;
    let parent_thread = ensure_primary_session_thread(&state, source_session.id).await?;

    let specialist_session = match input.specialist_session_id {
        Some(session_id) => {
            let session = state.get_session(session_id).await?;
            if session.agent_id != handoff.target_agent_id {
                return Err(AppError::bad_request(
                    "specialist_session_id must belong to the handoff target agent",
                ));
            }
            session
        }
        None => {
            let message = input.message.or_else(|| {
                Some(default_handoff_assignment_message(
                    &handoff,
                    &manager_plan,
                    &target_agent,
                ))
            });
            state
                .create_session(CreateSession {
                    agent_id: handoff.target_agent_id,
                    environment_id: source_session.environment_id,
                    title: input.title.unwrap_or_else(|| {
                        format!("Handoff {} for {}", handoff.intent, target_agent.name)
                    }),
                    message,
                })
                .await?
        }
    };
    ensure_primary_session_thread(&state, specialist_session.id).await?;
    let now = Utc::now();
    let assignment = state
        .create_agent_handoff_assignment(AgentHandoffAssignment {
            id: Uuid::new_v4(),
            agent_handoff_event_id: handoff.id,
            manager_plan_id,
            source_session_id: handoff.source_session_id,
            specialist_session_id: specialist_session.id,
            source_agent_id: handoff.source_agent_id,
            target_agent_id: handoff.target_agent_id,
            semantic_scopes: handoff.semantic_scopes.clone(),
            runtime_profile_id: handoff.runtime_profile_id,
            remote_computer_required: handoff.remote_computer_required,
            remote_computer_job_assignment_id: input.remote_computer_job_assignment_id,
            status: if handoff.remote_computer_required
                && input.remote_computer_job_assignment_id.is_none()
            {
                "waiting_remote_computer".to_string()
            } else {
                "assigned".to_string()
            },
            assigned_by: input.assigned_by.and_then(normalize_optional_text),
            metadata: input.metadata,
            audit_trace_id: None,
            created_at: now,
            updated_at: now,
        })
        .await?;
    let audit =
        record_agent_handoff_assignment_audit_and_events(&state, &assignment, &handoff).await?;
    let assignment = state
        .update_agent_handoff_assignment_audit_trace(assignment.id, audit.id)
        .await?;
    let child_thread = create_handoff_session_thread(
        &state,
        &assignment,
        &handoff,
        &specialist_session,
        Some(parent_thread.id),
    )
    .await?;
    materialize_workflow_handoff_assignment(
        &state,
        &handoff,
        &assignment,
        &manager_plan,
        &target_agent,
        &specialist_session,
        &child_thread,
    )
    .await?;
    state
        .append_event(
            "system",
            Some(child_thread.id),
            handoff.source_session_id,
            "thread.started",
            session_thread_event_payload(&child_thread),
        )
        .await?;
    state
        .append_event(
            "system",
            Some(child_thread.id),
            specialist_session.id,
            "thread.started",
            session_thread_event_payload(&child_thread),
        )
        .await?;
    Ok(Json(assignment))
}

async fn materialize_workflow_handoff_assignment(
    state: &AppState,
    handoff: &AgentHandoffEvent,
    assignment: &AgentHandoffAssignment,
    manager_plan: &ManagerAgentPlan,
    target_agent: &Agent,
    specialist_session: &Session,
    child_thread: &SessionThread,
) -> Result<Option<(WorkflowStepRun, TaskGrant)>, AppError> {
    let Some((run, parent_grant)) =
        active_task_grant_for_session(state, handoff.source_session_id).await?
    else {
        return Ok(None);
    };
    let step_id = Uuid::new_v4();
    let now = Utc::now();
    let objective = manager_plan
        .task_intake
        .get("goal")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(handoff.intent.as_str())
        .to_string();
    let child_grant = TaskGrant {
        id: Uuid::new_v4(),
        workflow_run_id: run.id,
        workflow_step_run_id: Some(step_id),
        session_id: Some(specialist_session.id),
        parent_grant_id: Some(parent_grant.id),
        source_event_id: None,
        source_handoff_id: Some(handoff.id),
        issuer_subject: assignment
            .assigned_by
            .clone()
            .unwrap_or_else(|| "system".to_string()),
        grantee_agent_id: Some(target_agent.id),
        grantee_session_id: Some(specialist_session.id),
        agent_class: Some("specialist".to_string()),
        objective,
        risk_level: handoff.risk_level.clone(),
        status: "active".to_string(),
        expires_at: parent_grant.expires_at,
        max_turns: parent_grant.max_turns,
        max_tool_calls: parent_grant.max_tool_calls,
        max_runtime_seconds: parent_grant.max_runtime_seconds,
        max_cost_usd_micros: parent_grant.max_cost_usd_micros,
        semantic_scopes: handoff.semantic_scopes.clone(),
        memory_scope: child_handoff_memory_scope(&parent_grant.memory_scope),
        tool_scope: child_tool_scope_for_agent(&parent_grant.tool_scope, target_agent),
        connector_scope: parent_grant.connector_scope.clone(),
        approval_policy: parent_grant.approval_policy.clone(),
        external_effects: parent_grant.external_effects.clone(),
        context_packet_id: None,
        policy_revision_id: parent_grant.policy_revision_id,
        immutable_args_hash: None,
        audit_trace_id: None,
        created_at: now,
        updated_at: now,
    };
    validate_task_grant_scope_objects(&child_grant)?;
    ensure_child_task_grant_within_parent(&parent_grant, &child_grant)?;

    let agent_version_id = Some(state.current_agent_version(target_agent.id).await?.id);
    let step = state
        .create_workflow_step_run(WorkflowStepRun {
            id: step_id,
            workflow_run_id: run.id,
            step_key: handoff.intent.clone(),
            step_type: "handoff".to_string(),
            agent_id: Some(target_agent.id),
            agent_version_id,
            session_id: Some(specialist_session.id),
            thread_id: Some(child_thread.id),
            handoff_id: Some(handoff.id),
            task_grant_id: None,
            environment_id: specialist_session.environment_id,
            status: if assignment.status == "waiting_remote_computer" {
                "requires_action".to_string()
            } else {
                "queued".to_string()
            },
            input_payload: json!({
                "agent_handoff_assignment_id": assignment.id,
                "agent_handoff_event_id": handoff.id,
                "manager_plan_id": manager_plan.id,
                "payload": handoff.payload.clone(),
                "semantic_scopes": handoff.semantic_scopes.clone(),
                "remote_computer_required": assignment.remote_computer_required
            }),
            output_payload: empty_json_object(),
            artifact_ids: Vec::new(),
            approval_ids: Vec::new(),
            tool_call_ids: Vec::new(),
            claimed_by_worker: None,
            lease_expires_at: None,
            context_packet_id: None,
            started_at: None,
            completed_at: None,
            scheduled_at: None,
            created_at: now,
            updated_at: now,
        })
        .await?;
    let child_grant = state.create_task_grant(child_grant).await?;
    record_task_grant_issued(state, &child_grant, run.primary_session_id).await?;
    let step = state
        .update_workflow_step_run_task_grant(step.id, child_grant.id)
        .await?;
    record_workflow_step_run_created(state, &run, &step).await?;
    Ok(Some((step, child_grant)))
}

fn child_handoff_memory_scope(parent: &Value) -> Value {
    let mut memory_scope = parent.clone();
    if let Some(object) = memory_scope.as_object_mut()
        && object.contains_key("writeback_allowed")
    {
        object.insert("writeback_allowed".to_string(), json!(false));
    }
    memory_scope
}

fn child_tool_scope_for_agent(parent: &Value, agent: &Agent) -> Value {
    let agent_tools = agent
        .tools
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let mut scope = serde_json::Map::new();
    for key in ["read", "write", "external_write"] {
        let values = parent
            .get(key)
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .filter_map(Value::as_str)
                    .flat_map(|tool| {
                        if tool == "*" {
                            agent_tools.iter().copied().collect::<Vec<_>>()
                        } else if agent_tools.contains(tool) {
                            vec![tool]
                        } else {
                            Vec::new()
                        }
                    })
                    .map(|tool| Value::String(tool.to_string()))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        scope.insert(key.to_string(), Value::Array(values));
    }
    Value::Object(scope)
}

async fn attach_agent_handoff_remote_computer_assignment(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<AttachAgentHandoffRemoteComputerAssignment>,
) -> Result<Json<AgentHandoffAssignment>, AppError> {
    let assignment = state.get_agent_handoff_assignment(id).await?;
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "session",
        Some(assignment.specialist_session_id),
    )
    .await?;
    if !assignment.remote_computer_required {
        return Err(AppError::bad_request(
            "agent handoff assignment does not require Remote Computer",
        ));
    }
    let remote_assignment = state
        .list_remote_computer_job_assignments()
        .await?
        .into_iter()
        .find(|candidate| candidate.id == input.remote_computer_job_assignment_id)
        .ok_or_else(|| AppError::not_found("remote computer job assignment not found"))?;
    if remote_assignment.session_id != assignment.specialist_session_id {
        return Err(AppError::bad_request(
            "remote computer job assignment must belong to the specialist session",
        ));
    }
    if remote_assignment.status != "assigned" {
        return Err(AppError::bad_request(
            "remote computer job assignment must be assigned",
        ));
    }
    let updated = state
        .attach_agent_handoff_assignment_remote_computer_job(
            assignment.id,
            remote_assignment.id,
            input.metadata,
        )
        .await?;
    record_agent_handoff_assignment_remote_computer_event(&state, &updated, &remote_assignment)
        .await?;
    if let Some(thread) = state
        .session_thread_for_handoff(updated.agent_handoff_event_id)
        .await?
    {
        let thread = state
            .update_session_thread_status(thread.id, "running")
            .await?;
        state
            .append_event(
                "system",
                Some(thread.id),
                updated.source_session_id,
                "thread.status_changed",
                session_thread_event_payload(&thread),
            )
            .await?;
        state
            .append_event(
                "system",
                Some(thread.id),
                updated.specialist_session_id,
                "thread.status_changed",
                session_thread_event_payload(&thread),
            )
            .await?;
    }
    Ok(Json(updated))
}

async fn transition_agent_handoff_event(
    state: AppState,
    id: Uuid,
    headers: HeaderMap,
    input: TransitionAgentHandoffEvent,
    next_status: &str,
) -> Result<Json<AgentHandoffEvent>, AppError> {
    let current = state.get_agent_handoff_event(id).await?;
    let permission = if next_status == "accepted"
        && (current.approval_required || current.risk_level == "high")
    {
        Permission::ApprovalsDecide
    } else {
        Permission::SessionsRun
    };
    authorize_request(
        &state,
        &headers,
        permission,
        "session",
        Some(current.source_session_id),
    )
    .await?;
    ensure_agent_handoff_transition(&current.status, next_status)?;
    let event_type = format!("agent_handoff.{next_status}");
    let audit =
        record_agent_handoff_audit_and_event(&state, &current, &event_type, input.reason).await?;
    let updated = state
        .update_agent_handoff_event_status(current.id, next_status, Some(audit.id))
        .await?;
    if matches!(next_status, "completed" | "failed")
        && let Some(thread) = state.session_thread_for_handoff(current.id).await?
    {
        let status = if next_status == "completed" {
            "terminated"
        } else {
            "failed"
        };
        let thread = state
            .update_session_thread_status(thread.id, status)
            .await?;
        state
            .append_event(
                "system",
                Some(thread.id),
                current.source_session_id,
                "thread.status_changed",
                session_thread_event_payload(&thread),
            )
            .await?;
        if let Some(specialist_session_id) = thread.specialist_session_id {
            state
                .append_event(
                    "system",
                    Some(thread.id),
                    specialist_session_id,
                    "thread.status_changed",
                    session_thread_event_payload(&thread),
                )
                .await?;
        }
    }
    Ok(Json(updated))
}

async fn record_agent_handoff_audit_and_event(
    state: &AppState,
    handoff: &AgentHandoffEvent,
    action: &str,
    reason: Option<String>,
) -> Result<AuditLog, AppError> {
    let details = json!({
        "agent_handoff_event_id": handoff.id,
        "source_session_id": handoff.source_session_id,
        "source_agent_id": handoff.source_agent_id,
        "target_agent_id": handoff.target_agent_id,
        "manager_plan_id": handoff.manager_plan_id,
        "intent": handoff.intent,
        "schema_version": handoff.schema_version,
        "risk_level": handoff.risk_level,
        "approval_required": handoff.approval_required,
        "semantic_scopes": handoff.semantic_scopes,
        "runtime_profile_id": handoff.runtime_profile_id,
        "remote_computer_required": handoff.remote_computer_required,
        "review_status": handoff.review_status,
        "human_escalation_status": handoff.human_escalation_status,
        "status": handoff.status,
        "reason": reason,
    });
    state
        .append_event(
            "agent",
            Some(handoff.source_agent_id),
            handoff.source_session_id,
            action,
            details.clone(),
        )
        .await?;
    state
        .append_audit_log(new_audit_log(
            Some(handoff.source_session_id),
            "agent",
            Some(handoff.source_agent_id),
            action,
            "agent_handoff_event",
            Some(handoff.id),
            details,
        ))
        .await
}

