async fn poll_codex_app_server_run_inner(
    state: &AppState,
    run_id: Uuid,
    input: CodexAppServerPollRequest,
    actor_type: &str,
    subject: String,
) -> Result<CodexAppServerPollResponse, AppError> {
    let config = codex_app_server_config(state)?;
    let run = state.get_codex_app_server_run(run_id).await?;
    let turn_id = run
        .turn_id
        .clone()
        .ok_or_else(|| AppError::bad_request("Codex App Server run has no turn_id to poll"))?;
    let max_attempts = input.max_attempts.clamp(1, 10);
    let retry_interval_ms = input.retry_interval_ms.min(5_000);
    let mut attempts = 0;
    let mut last_status = run.status.clone();
    let mut terminal = false;
    let mut updated = run;

    while attempts < max_attempts && !terminal {
        attempts += 1;
        match state
            .codex_app_server_client
            .get_turn_status(config, &turn_id)
            .await
        {
            Ok(response) => {
                last_status = response
                    .status
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string());
                terminal = codex_turn_status_is_terminal(&last_status);
                updated = state
                    .update_codex_app_server_run_status(
                        run_id,
                        last_status.clone(),
                        serde_json::to_value(&response)?,
                        None,
                    )
                    .await?;
            }
            Err(error) => {
                last_status = "poll_failed".to_string();
                updated = state
                    .update_codex_app_server_run_status(
                        run_id,
                        last_status.clone(),
                        updated.response.clone(),
                        Some(json!({"message": error.message, "attempt": attempts})),
                    )
                    .await?;
                terminal = attempts >= max_attempts;
            }
        }
        if attempts < max_attempts && !terminal && retry_interval_ms > 0 {
            tokio::time::sleep(Duration::from_millis(retry_interval_ms)).await;
        }
    }

    let response = CodexAppServerPollResponse {
        run: updated,
        attempts,
        terminal,
        last_status,
    };
    state
        .append_audit_log(new_audit_log(
            None,
            actor_type,
            None,
            "codex_app_server.run_polled",
            "codex_app_server_run",
            Some(run_id),
            json!({
                "subject": subject,
                "run_id": run_id,
                "turn_id": turn_id,
                "attempts": response.attempts,
                "terminal": response.terminal,
                "last_status": response.last_status,
            }),
        ))
        .await?;
    Ok(response)
}

async fn execute_stale_codex_app_server_polls(
    state: &AppState,
    input: CodexAppServerStalePollRequest,
    actor_type: &str,
    subject: &str,
) -> Result<CodexAppServerStalePollRun, AppError> {
    let checked_at = Utc::now();
    let stale_after_seconds = input.stale_after_seconds.min(86_400);
    let max_runs = input.max_runs.clamp(1, 100);
    let runs = state.list_codex_app_server_runs().await?;
    let candidates = select_stale_codex_app_server_runs(&runs, checked_at, stale_after_seconds);
    let candidate_count = candidates.len();
    let mut results = Vec::new();
    let mut polled_count = 0usize;
    let mut terminal_count = 0usize;
    let mut failed_count = 0usize;
    let mut skipped_count = candidate_count.saturating_sub(max_runs);

    if state.codex_app_server_config.is_none() {
        skipped_count = candidate_count;
        for run in candidates {
            results.push(json!({
                "run_id": run.id,
                "turn_id": run.turn_id,
                "status": "skipped",
                "reason": "codex_app_server_reserved",
            }));
        }
    } else {
        for run in candidates.into_iter().take(max_runs) {
            let poll_input = CodexAppServerPollRequest {
                max_attempts: input.max_attempts,
                retry_interval_ms: input.retry_interval_ms,
            };
            match poll_codex_app_server_run_inner(
                state,
                run.id,
                poll_input,
                actor_type,
                subject.to_string(),
            )
            .await
            {
                Ok(response) => {
                    polled_count += 1;
                    if response.terminal {
                        terminal_count += 1;
                    }
                    results.push(json!({
                        "run_id": response.run.id,
                        "turn_id": response.run.turn_id,
                        "status": "polled",
                        "last_status": response.last_status,
                        "attempts": response.attempts,
                        "terminal": response.terminal,
                    }));
                }
                Err(error) => {
                    failed_count += 1;
                    results.push(json!({
                        "run_id": run.id,
                        "turn_id": run.turn_id,
                        "status": "failed",
                        "error": error.message,
                    }));
                }
            }
        }
    }

    let run = CodexAppServerStalePollRun {
        checked_at,
        stale_after_seconds,
        candidate_count,
        polled_count,
        terminal_count,
        skipped_count,
        failed_count,
        results,
    };
    state
        .append_audit_log(new_audit_log(
            None,
            actor_type,
            None,
            "codex_app_server.stale_poll_due_run",
            "codex_app_server",
            None,
            json!({
                "subject": subject,
                "stale_after_seconds": run.stale_after_seconds,
                "candidate_count": run.candidate_count,
                "polled_count": run.polled_count,
                "terminal_count": run.terminal_count,
                "skipped_count": run.skipped_count,
                "failed_count": run.failed_count,
            }),
        ))
        .await?;
    Ok(run)
}

fn select_stale_codex_app_server_runs(
    runs: &[CodexAppServerRun],
    now: DateTime<Utc>,
    stale_after_seconds: u64,
) -> Vec<CodexAppServerRun> {
    let cutoff = now - chrono::Duration::seconds(stale_after_seconds as i64);
    let mut latest_by_turn = BTreeMap::<String, &CodexAppServerRun>::new();
    for run in runs {
        let Some(turn_id) = run.turn_id.as_ref() else {
            continue;
        };
        if !run.operation.starts_with("turn.") {
            continue;
        }
        if codex_turn_status_is_terminal(&run.status) || run.created_at > cutoff {
            continue;
        }
        latest_by_turn
            .entry(turn_id.clone())
            .and_modify(|existing| {
                if existing.created_at < run.created_at {
                    *existing = run;
                }
            })
            .or_insert(run);
    }
    let mut candidates = latest_by_turn.into_values().cloned().collect::<Vec<_>>();
    candidates.sort_by_key(|run| run.created_at);
    candidates
}

fn codex_turn_status_is_terminal(status: &str) -> bool {
    matches!(
        status.trim().to_ascii_lowercase().as_str(),
        "completed" | "failed" | "cancelled" | "canceled" | "interrupted"
    )
}

fn build_codex_app_server_trace_summary(runs: &[CodexAppServerRun]) -> CodexAppServerTraceSummary {
    let mut by_status = HashMap::new();
    let mut by_operation = HashMap::new();
    let mut by_failure_domain = HashMap::new();
    let mut grouped = BTreeMap::<String, Vec<&CodexAppServerRun>>::new();
    for run in runs {
        increment_count(&mut by_status, run.status.as_str());
        increment_count(&mut by_operation, run.operation.as_str());
        grouped
            .entry(codex_app_server_trace_key(run))
            .or_default()
            .push(run);
    }
    let mut traces = Vec::new();
    for (trace_key, mut group) in grouped {
        group.sort_by_key(|run| run.created_at);
        let first = group.first().expect("group has at least one run");
        let latest = group.last().expect("group has at least one run");
        let mut operations = BTreeSet::new();
        let mut command_ids = BTreeSet::new();
        let mut command_count = 0usize;
        let mut poll_count = 0usize;
        let mut error_count = 0usize;
        for run in &group {
            operations.insert(run.operation.clone());
            if run.operation.contains("command") || run.command_id.is_some() {
                command_count += 1;
            }
            if let Some(command_id) = run.command_id.as_ref() {
                command_ids.insert(command_id.clone());
            }
            if run.operation.contains("poll") {
                poll_count += 1;
            }
            if run.error.is_some() || codex_run_status_failed(&run.status) {
                error_count += 1;
            }
        }
        let latest_status = latest.status.clone();
        let terminal = codex_turn_status_is_terminal(&latest_status);
        let latest_error = group.iter().rev().find_map(|run| run.error.clone());
        let dashboard = build_codex_trace_dashboard(&group, &[], 0, terminal);
        increment_count(&mut by_failure_domain, dashboard.failure_domain.as_str());
        traces.push(CodexTurnTrace {
            trace_key,
            turn_id: latest.turn_id.clone().or_else(|| first.turn_id.clone()),
            thread_id: latest.thread_id.clone().or_else(|| first.thread_id.clone()),
            latest_run_id: latest.id,
            latest_status: latest_status.clone(),
            terminal,
            run_count: group.len(),
            command_count,
            poll_count,
            error_count,
            duration_seconds: (latest.created_at - first.created_at).num_seconds(),
            command_ids: command_ids.into_iter().collect(),
            operations: operations.into_iter().collect(),
            next_action: dashboard.operator_action.clone(),
            latest_error,
            dashboard,
            first_seen_at: first.created_at,
            last_seen_at: latest.created_at,
        });
    }
    traces.sort_by(|left, right| right.last_seen_at.cmp(&left.last_seen_at));
    let active_turn_count = traces
        .iter()
        .filter(|trace| trace.turn_id.is_some() && !trace.terminal)
        .count();
    let failed_turn_count = traces
        .iter()
        .filter(|trace| codex_run_status_failed(&trace.latest_status) || trace.error_count > 0)
        .count();
    CodexAppServerTraceSummary {
        generated_at: Utc::now(),
        run_count: runs.len(),
        turn_count: traces
            .iter()
            .filter(|trace| trace.turn_id.is_some())
            .count(),
        active_turn_count,
        failed_turn_count,
        by_status,
        by_operation,
        by_failure_domain,
        traces,
    }
}

fn build_codex_app_server_control_plane_summary(
    config: Option<&CodexAppServerConfig>,
    runs: &[CodexAppServerRun],
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
) -> CodexAppServerControlPlaneSummary {
    let trace_summary = build_codex_app_server_trace_summary(runs);
    let stale_candidates =
        select_stale_codex_app_server_runs(runs, generated_at, default_codex_stale_after_seconds());
    let stale_candidate_count = stale_candidates.len();
    let pollable_turn_count = trace_summary
        .traces
        .iter()
        .filter(|trace| trace.turn_id.is_some() && !trace.terminal)
        .count();
    let latest_seen_at = trace_summary
        .traces
        .iter()
        .map(|trace| trace.last_seen_at)
        .max()
        .or_else(|| runs.iter().map(|run| run.created_at).max());
    let mut attention_items = Vec::new();

    if config.is_none() {
        attention_items.push(CodexAppServerControlPlaneAttentionItem {
            kind: "reserved_adapter".to_string(),
            severity: "warning".to_string(),
            message:
                "Codex App Server is reserved until MANDOFORGE_CODEX_APP_SERVER_URL is configured"
                    .to_string(),
            trace_key: None,
            turn_id: None,
        });
    }
    for trace in &trace_summary.traces {
        if codex_run_status_failed(&trace.latest_status) || trace.error_count > 0 {
            attention_items.push(CodexAppServerControlPlaneAttentionItem {
                kind: "failed_trace".to_string(),
                severity: "critical".to_string(),
                message: format!(
                    "trace latest status is {} with {} error signals",
                    trace.latest_status, trace.error_count
                ),
                trace_key: Some(trace.trace_key.clone()),
                turn_id: trace.turn_id.clone(),
            });
        } else if trace.turn_id.is_some() && !trace.terminal {
            attention_items.push(CodexAppServerControlPlaneAttentionItem {
                kind: "active_turn".to_string(),
                severity: "warning".to_string(),
                message: "turn is still non-terminal and should be polled or interrupted"
                    .to_string(),
                trace_key: Some(trace.trace_key.clone()),
                turn_id: trace.turn_id.clone(),
            });
        }
    }
    for run in stale_candidates {
        attention_items.push(CodexAppServerControlPlaneAttentionItem {
            kind: "stale_turn".to_string(),
            severity: if config.is_some() {
                "warning".to_string()
            } else {
                "critical".to_string()
            },
            message: format!(
                "turn has not reached a terminal state within {} seconds",
                default_codex_stale_after_seconds()
            ),
            trace_key: Some(codex_app_server_trace_key(&run)),
            turn_id: run.turn_id,
        });
    }

    let timeout_seconds = config.map(|config| config.timeout_seconds);
    let lookup = |key: &str| std::env::var(key).ok();
    let production_ops = build_codex_app_server_production_ops_readiness(
        config.is_some(),
        &trace_summary,
        stale_candidate_count,
        audit_logs,
        generated_at,
        codex_app_server_ops_controller_required(&lookup),
        codex_app_server_ops_controller_configured(&lookup),
    );
    let deployment_readiness = build_codex_app_server_deployment_readiness(
        config.is_some(),
        audit_logs,
        generated_at,
        codex_app_server_deployment_controller_required(&lookup),
        codex_app_server_deployment_controller_configured(&lookup),
    );
    if production_ops.production_blocked {
        attention_items.push(CodexAppServerControlPlaneAttentionItem {
            kind: "production_ops_blocked".to_string(),
            severity: if production_ops.status == "blocked" {
                "critical".to_string()
            } else {
                "warning".to_string()
            },
            message: production_ops.message.clone(),
            trace_key: None,
            turn_id: None,
        });
    }
    if deployment_readiness.production_blocked {
        attention_items.push(CodexAppServerControlPlaneAttentionItem {
            kind: "deployment_validation_blocked".to_string(),
            severity: if deployment_readiness.status == "blocked" {
                "critical".to_string()
            } else {
                "warning".to_string()
            },
            message: deployment_readiness.message.clone(),
            trace_key: None,
            turn_id: None,
        });
    }
    let status = if config.is_none() {
        "reserved"
    } else if attention_items
        .iter()
        .any(|item| item.severity == "critical")
    {
        "critical"
    } else if attention_items.is_empty() {
        "ready"
    } else {
        "attention"
    }
    .to_string();

    CodexAppServerControlPlaneSummary {
        generated_at,
        configured: config.is_some(),
        status,
        endpoint_configured: config.is_some(),
        timeout_seconds,
        run_count: trace_summary.run_count,
        turn_count: trace_summary.turn_count,
        active_turn_count: trace_summary.active_turn_count,
        failed_turn_count: trace_summary.failed_turn_count,
        stale_candidate_count,
        pollable_turn_count,
        latest_seen_at,
        by_status: trace_summary.by_status,
        by_operation: trace_summary.by_operation,
        production_ops,
        deployment_readiness,
        attention_items,
    }
}

fn build_codex_trace_dashboard(
    runs: &[&CodexAppServerRun],
    evidence: &[CodexTraceEvidence],
    artifact_lineage_count: usize,
    terminal: bool,
) -> CodexTraceDashboard {
    let mut dashboard = CodexTraceDashboard::default();
    for run in runs {
        if run.operation.contains("command") || run.command_id.is_some() {
            dashboard.command_count += 1;
        }
        if run.operation.contains("poll") {
            dashboard.poll_count += 1;
        }
        if run.operation.contains("interrupt") {
            dashboard.interrupt_count += 1;
        }
        if run.error.is_some() || codex_run_status_failed(&run.status) {
            dashboard.failed_operation_count += 1;
        }
    }
    for item in evidence {
        match item.kind.as_str() {
            "poll" => dashboard.poll_count += 1,
            "interrupt" => dashboard.interrupt_count += 1,
            "worker_lease" => dashboard.worker_lease_count += 1,
            "retry" => dashboard.retry_count += 1,
            "fallback" => dashboard.fallback_count += 1,
            "artifact_sync" => dashboard.artifact_sync_count += 1,
            "failed" => dashboard.failed_operation_count += 1,
            _ => {}
        }
    }
    dashboard.artifact_sync_count = dashboard.artifact_sync_count.max(artifact_lineage_count);
    dashboard.stuck = runs
        .last()
        .is_some_and(|run| run.turn_id.is_some() && !terminal);
    dashboard.failure_domain =
        if dashboard.fallback_count > 0 && dashboard.failed_operation_count > 0 {
            "fallback"
        } else if dashboard.retry_count > 0 && dashboard.failed_operation_count > 0 {
            "worker_lease"
        } else if dashboard.failed_operation_count > 0
            && runs
                .last()
                .is_some_and(|run| run.operation.contains("poll") || run.status == "poll_failed")
        {
            "poll"
        } else if dashboard.failed_operation_count > 0 && dashboard.interrupt_count > 0 {
            "interrupt"
        } else if dashboard.failed_operation_count > 0 && dashboard.command_count > 0 {
            "command"
        } else if dashboard.failed_operation_count > 0 {
            "provider"
        } else if dashboard.stuck {
            "non_terminal_poll"
        } else {
            "none"
        }
        .to_string();
    dashboard.operator_action = match dashboard.failure_domain.as_str() {
        "none" if terminal && dashboard.artifact_sync_count > 0 => "inspect_artifact_lineage",
        "none" if terminal => "complete",
        "none" => "observe",
        "non_terminal_poll" => "poll_or_interrupt",
        "fallback" => "inspect_fallback_reason",
        "worker_lease" => "inspect_worker_retry",
        "poll" => "inspect_poll_failure",
        "interrupt" => "inspect_interrupt_reason",
        "command" => "inspect_command_failure",
        _ => "inspect_provider_error",
    }
    .to_string();
    dashboard
}

fn codex_trace_evidence(
    runs: &[CodexAppServerRun],
    events: &[SessionEvent],
    audit_logs: &[AuditLog],
) -> Vec<CodexTraceEvidence> {
    let run_ids = runs.iter().map(|run| run.id).collect::<HashSet<_>>();
    let turn_ids = runs
        .iter()
        .filter_map(|run| run.turn_id.clone())
        .collect::<HashSet<_>>();
    let command_ids = runs
        .iter()
        .filter_map(|run| run.command_id.clone())
        .collect::<HashSet<_>>();
    let session_ids = codex_trace_session_ids(runs);
    let mut evidence = Vec::new();
    for event in events {
        let Some(kind) = codex_trace_event_kind(event) else {
            continue;
        };
        if !codex_trace_event_matches(event, &run_ids, &turn_ids, &command_ids, &session_ids) {
            continue;
        }
        evidence.push(CodexTraceEvidence {
            source: "session_event".to_string(),
            kind,
            message: codex_trace_event_message(event),
            run_id: value_uuid(&event.payload, "run_id"),
            event_id: Some(event.id),
            audit_log_id: None,
            session_id: Some(event.session_id),
            created_at: event.created_at,
            details: json!({
                "event_type": event.event_type,
                "actor_type": event.actor_type,
                "actor_id": event.actor_id,
                "payload": event.payload,
            }),
        });
    }
    for log in audit_logs {
        let Some(kind) = codex_trace_audit_kind(log) else {
            continue;
        };
        if !codex_trace_audit_matches(log, &run_ids, &turn_ids, &command_ids, &session_ids) {
            continue;
        }
        evidence.push(CodexTraceEvidence {
            source: "audit_log".to_string(),
            kind,
            message: codex_trace_audit_message(log),
            run_id: value_uuid(&log.details, "run_id"),
            event_id: None,
            audit_log_id: Some(log.id),
            session_id: log.session_id,
            created_at: log.created_at,
            details: json!({
                "action": log.action,
                "actor_type": log.actor_type,
                "actor_id": log.actor_id,
                "resource_type": log.resource_type,
                "resource_id": log.resource_id,
                "details": log.details,
            }),
        });
    }
    evidence.sort_by_key(|item| item.created_at);
    evidence
}

fn codex_trace_artifact_lineage(
    runs: &[CodexAppServerRun],
    audit_logs: &[AuditLog],
) -> Vec<CodexTraceArtifactLineage> {
    let turn_ids = runs
        .iter()
        .filter_map(|run| run.turn_id.clone())
        .collect::<HashSet<_>>();
    let command_ids = runs
        .iter()
        .filter_map(|run| run.command_id.clone())
        .collect::<HashSet<_>>();
    let session_ids = codex_trace_session_ids(runs);
    let mut lineage = audit_logs
        .iter()
        .filter(|log| log.action == "codex_app_server.artifact_synced")
        .filter(|log| {
            codex_trace_audit_matches(log, &HashSet::new(), &turn_ids, &command_ids, &session_ids)
        })
        .filter_map(|log| {
            let artifact_id = log
                .resource_id
                .or_else(|| value_uuid(&log.details, "artifact_id"))?;
            Some(CodexTraceArtifactLineage {
                artifact_id,
                session_id: log.session_id,
                turn_id: value_string(&log.details, "turn_id"),
                command_id: value_string(&log.details, "command_id"),
                name: value_string(&log.details, "name"),
                path: value_string(&log.details, "path"),
                artifact_type: value_string(&log.details, "artifact_type"),
                created_at: log.created_at,
            })
        })
        .collect::<Vec<_>>();
    lineage.sort_by_key(|item| item.created_at);
    lineage
}

fn codex_trace_session_ids(runs: &[CodexAppServerRun]) -> HashSet<Uuid> {
    let mut session_ids = HashSet::new();
    for run in runs {
        for value in [
            run.request.get("session_id"),
            run.response.get("session_id"),
            run.request.pointer("/metadata/session_id"),
            run.response.pointer("/metadata/session_id"),
        ]
        .into_iter()
        .flatten()
        {
            if let Some(session_id) = value.as_str().and_then(|value| Uuid::parse_str(value).ok()) {
                session_ids.insert(session_id);
            }
        }
    }
    session_ids
}

fn codex_trace_event_kind(event: &SessionEvent) -> Option<String> {
    let kind = match event.event_type.as_str() {
        "codex.task.event" => "poll",
        "codex.task.fallback" => "fallback",
        "codex.task.failed" => "failed",
        "codex.task.started" | "codex.task.completed" => "worker_lease",
        "execution.queued" => "worker_lease",
        "execution.retry_queued" => "retry",
        "artifact.created"
            if event.payload.get("source").and_then(Value::as_str) == Some("codex_app_server") =>
        {
            "artifact_sync"
        }
        _ => return None,
    };
    Some(kind.to_string())
}

fn codex_trace_audit_kind(log: &AuditLog) -> Option<String> {
    let kind = match log.action.as_str() {
        "codex_app_server.run_polled" => "poll",
        "codex_app_server.artifact_synced" => "artifact_sync",
        _ => return None,
    };
    Some(kind.to_string())
}

fn codex_trace_event_matches(
    event: &SessionEvent,
    run_ids: &HashSet<Uuid>,
    turn_ids: &HashSet<String>,
    command_ids: &HashSet<String>,
    session_ids: &HashSet<Uuid>,
) -> bool {
    value_uuid(&event.payload, "run_id").is_some_and(|run_id| run_ids.contains(&run_id))
        || value_string(&event.payload, "turn_id")
            .is_some_and(|turn_id| turn_ids.contains(&turn_id))
        || value_string(&event.payload, "command_id")
            .is_some_and(|command_id| command_ids.contains(&command_id))
        || (!session_ids.is_empty() && session_ids.contains(&event.session_id))
}

fn codex_trace_audit_matches(
    log: &AuditLog,
    run_ids: &HashSet<Uuid>,
    turn_ids: &HashSet<String>,
    command_ids: &HashSet<String>,
    session_ids: &HashSet<Uuid>,
) -> bool {
    value_uuid(&log.details, "run_id").is_some_and(|run_id| run_ids.contains(&run_id))
        || value_string(&log.details, "turn_id").is_some_and(|turn_id| turn_ids.contains(&turn_id))
        || value_string(&log.details, "command_id")
            .is_some_and(|command_id| command_ids.contains(&command_id))
        || log
            .session_id
            .is_some_and(|session_id| session_ids.contains(&session_id))
}

fn codex_trace_event_message(event: &SessionEvent) -> String {
    if let Some(error) = event.payload.get("error").and_then(Value::as_str) {
        return error.to_string();
    }
    if let Some(reason) = event.payload.get("reason").and_then(Value::as_str) {
        return reason.to_string();
    }
    if let Some(status) = event.payload.get("status").and_then(Value::as_str) {
        return format!("{} status {status}", event.event_type);
    }
    event.event_type.clone()
}

fn codex_trace_audit_message(log: &AuditLog) -> String {
    if let Some(status) = log
        .details
        .get("last_status")
        .or_else(|| log.details.get("status"))
        .and_then(Value::as_str)
    {
        return format!("{} status {status}", log.action);
    }
    if let Some(name) = log.details.get("name").and_then(Value::as_str) {
        return format!("{} {name}", log.action);
    }
    log.action.clone()
}

fn value_string(value: &Value, key: &str) -> Option<String> {
    value.get(key).and_then(Value::as_str).map(str::to_string)
}

fn value_uuid(value: &Value, key: &str) -> Option<Uuid> {
    value
        .get(key)
        .and_then(Value::as_str)
        .and_then(|value| Uuid::parse_str(value).ok())
}

fn build_codex_app_server_production_ops_readiness(
    configured: bool,
    trace_summary: &CodexAppServerTraceSummary,
    stale_candidate_count: usize,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> CodexAppServerProductionOpsReadiness {
    let latest_stale_poll = audit_logs
        .iter()
        .filter(|log| log.action == "codex_app_server.stale_poll_due_run")
        .max_by_key(|log| log.created_at);
    let latest_stale_poll_at = latest_stale_poll.map(|log| log.created_at);
    let latest_stale_poll_age_hours =
        latest_stale_poll_at.map(|created_at| (generated_at - created_at).num_hours());
    let latest_stale_poll_candidate_count = latest_stale_poll
        .and_then(|log| log.details.get("candidate_count"))
        .and_then(|value| value.as_u64())
        .unwrap_or(0) as usize;
    let latest_stale_poll_failed_count = latest_stale_poll
        .and_then(|log| log.details.get("failed_count"))
        .and_then(|value| value.as_u64())
        .unwrap_or(0) as usize;
    let latest_controller_log = audit_logs
        .iter()
        .filter(|log| log.action == "codex_app_server.ops_validation")
        .max_by_key(|log| log.created_at);
    let latest_controller_status = latest_controller_log
        .and_then(|log| {
            log.details["controller_execution"]["status"]
                .as_str()
                .or_else(|| log.details["status"].as_str())
        })
        .map(str::to_string);
    let latest_controller_age_hours =
        latest_controller_log.map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    let mut blocking_reasons = Vec::new();
    if !configured {
        blocking_reasons.push("adapter endpoint is not configured".to_string());
    }
    if trace_summary.failed_turn_count > 0 {
        blocking_reasons.push("failed/interrupted turn traces are present".to_string());
    }
    if stale_candidate_count > 0 {
        blocking_reasons.push("stale non-terminal turns are present".to_string());
    }
    if latest_stale_poll.is_none() {
        blocking_reasons.push("stale-turn supervision has not run".to_string());
    }
    if latest_stale_poll_failed_count > 0 {
        blocking_reasons.push("latest stale-turn poll run failed".to_string());
    }
    if latest_stale_poll_age_hours.is_some_and(|hours| hours >= 24) {
        blocking_reasons.push("stale-turn supervision is stale".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons
            .push("Codex App Server ops controller is required but not configured".to_string());
    }
    if controller_required && !latest_controller_validated {
        blocking_reasons.push(
            "Codex App Server ops controller evidence is missing or not validated".to_string(),
        );
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("Codex App Server ops controller evidence is stale".to_string());
    }
    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else if trace_summary.active_turn_count > 0 {
        "attention"
    } else {
        "ready"
    };
    let message = if production_blocked {
        format!(
            "Codex App Server production ops are blocked: {}",
            blocking_reasons.join("; ")
        )
    } else if trace_summary.active_turn_count > 0 {
        "Codex App Server has active non-terminal turns, but stale-turn supervision and required ops controller evidence are fresh".to_string()
    } else {
        "Codex App Server stale-turn supervision, turn traces, and required ops controller evidence are ready".to_string()
    };
    CodexAppServerProductionOpsReadiness {
        status: status.to_string(),
        production_blocked,
        configured,
        run_count: trace_summary.run_count,
        active_turn_count: trace_summary.active_turn_count,
        failed_turn_count: trace_summary.failed_turn_count,
        stale_candidate_count,
        latest_stale_poll_at,
        latest_stale_poll_age_hours,
        latest_stale_poll_candidate_count,
        latest_stale_poll_failed_count,
        controller_required,
        controller_configured,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        message,
    }
}

fn build_codex_app_server_deployment_readiness(
    configured: bool,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> CodexAppServerDeploymentReadiness {
    let latest_validation = audit_logs
        .iter()
        .filter(|log| log.action == "codex_app_server.deployment_validation")
        .max_by_key(|log| log.created_at);
    let controller_validation_logs = audit_logs
        .iter()
        .filter(|log| {
            log.action == "codex_app_server.deployment_validation"
                && log
                    .details
                    .get("controller_execution")
                    .and_then(|execution| execution.get("attempted"))
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
        })
        .collect::<Vec<_>>();
    let controller_execution_count = controller_validation_logs.len();
    let controller_failed_count = controller_validation_logs
        .iter()
        .filter(|log| {
            log.details
                .get("controller_execution")
                .and_then(|execution| execution.get("status"))
                .and_then(Value::as_str)
                .is_some_and(|status| status != "validated")
        })
        .count();
    let latest_validation_at = latest_validation.map(|log| log.created_at);
    let latest_validation_age_hours =
        latest_validation_at.map(|created_at| (generated_at - created_at).num_hours());
    let latest_validation_status = latest_validation
        .and_then(|log| log.details.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_validation_healthy = latest_validation
        .and_then(|log| log.details.get("healthy"))
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let latest_controller_status = latest_validation
        .and_then(|log| log.details.get("controller_execution"))
        .and_then(|execution| execution.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_age_hours = latest_validation
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_validated = latest_controller_status.as_deref() == Some("validated");
    let mut blocking_reasons = Vec::new();

    if !configured {
        blocking_reasons.push("Codex App Server endpoint is not configured".to_string());
    }
    if latest_validation.is_none() {
        blocking_reasons.push("deployment validation has not run".to_string());
    }
    if latest_validation.is_some() && !latest_validation_healthy {
        blocking_reasons.push("latest deployment validation was not healthy".to_string());
    }
    if latest_validation_age_hours.is_some_and(|hours| hours >= 24) {
        blocking_reasons.push("deployment validation evidence is stale".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons.push(
            "Codex App Server deployment controller is required but not configured".to_string(),
        );
    }
    if controller_required && controller_configured && !latest_controller_validated {
        blocking_reasons.push(
            "Codex App Server deployment controller evidence is missing or not validated"
                .to_string(),
        );
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons
            .push("Codex App Server deployment controller evidence is stale".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Codex App Server deployment validation is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Codex App Server deployment has a recent healthy validation run".to_string()
    };

    CodexAppServerDeploymentReadiness {
        status,
        production_blocked,
        configured,
        endpoint_configured: configured,
        deployment_validated: latest_validation_healthy && !production_blocked,
        latest_validation_at,
        latest_validation_age_hours,
        latest_validation_status,
        latest_validation_healthy,
        controller_required,
        controller_configured,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        controller_execution_count,
        controller_failed_count,
        blocking_reasons,
        message,
    }
}

fn codex_app_server_deployment_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_CODEX_APP_SERVER_DEPLOYMENT_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

fn codex_app_server_deployment_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_CODEX_APP_SERVER_DEPLOYMENT_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

fn codex_app_server_ops_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_CODEX_APP_SERVER_OPS_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

fn codex_app_server_ops_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_CODEX_APP_SERVER_OPS_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

async fn execute_codex_app_server_ops_controller<F>(
    lookup: &F,
    subject: Option<&str>,
    checked_at: DateTime<Utc>,
    summary: &CodexAppServerControlPlaneSummary,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_CODEX_APP_SERVER_OPS_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_CODEX_APP_SERVER_OPS_CONTROLLER_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_CODEX_APP_SERVER_OPS_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_CODEX_APP_SERVER_OPS_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.codex_app_server_ops",
        "subject": subject,
        "checked_at": checked_at,
        "control_plane": {
            "configured": summary.configured,
            "status": summary.status,
            "endpoint_configured": summary.endpoint_configured,
            "timeout_seconds": summary.timeout_seconds,
            "run_count": summary.run_count,
            "turn_count": summary.turn_count,
            "active_turn_count": summary.active_turn_count,
            "failed_turn_count": summary.failed_turn_count,
            "stale_candidate_count": summary.stale_candidate_count,
            "pollable_turn_count": summary.pollable_turn_count,
            "production_ops": summary.production_ops,
            "deployment_readiness": summary.deployment_readiness,
        },
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "Codex App Server ops controller failed with status {http_status}"
        )));
    }
    let controller_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("validated");
    let validated = matches!(controller_status, "validated" | "success" | "ok");
    Ok(json!({
        "attempted": true,
        "status": if validated { "validated" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": controller_status,
        "ops_id": body.get("ops_id").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "checks": body.get("checks").cloned().unwrap_or_else(|| json!([])),
    }))
}

async fn execute_codex_app_server_deployment_controller<F>(
    lookup: &F,
    subject: &str,
    checked_at: DateTime<Utc>,
    config: &CodexAppServerConfig,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_CODEX_APP_SERVER_DEPLOYMENT_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request(
                "MANDOFORGE_CODEX_APP_SERVER_DEPLOYMENT_CONTROLLER_URL is required",
            )
        })?;
    let timeout_seconds = lookup("MANDOFORGE_CODEX_APP_SERVER_DEPLOYMENT_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_CODEX_APP_SERVER_DEPLOYMENT_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let payload = json!({
        "type": "mandoforge.codex_app_server_deployment",
        "subject": subject,
        "checked_at": checked_at,
        "app_server": {
            "endpoint_configured": true,
            "timeout_seconds": config.timeout_seconds,
            "endpoint": config.endpoint.as_str(),
        }
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "Codex App Server deployment controller failed with status {http_status}"
        )));
    }
    let controller_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("validated");
    let validated = matches!(
        controller_status,
        "validated" | "deployed" | "healthy" | "success" | "ok"
    );
    Ok(json!({
        "attempted": true,
        "status": if validated { "validated" } else { "failed" },
        "http_status": http_status.as_u16(),
        "provider_status": controller_status,
        "deployment_id": body.get("deployment_id").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "steps": body.get("steps").cloned().unwrap_or_else(|| json!([])),
    }))
}

fn build_codex_app_server_trace_detail(
    runs: &[CodexAppServerRun],
    trace_key: &str,
    events: &[SessionEvent],
    audit_logs: &[AuditLog],
) -> Result<CodexAppServerTraceDetail, AppError> {
    let mut matching = runs
        .iter()
        .filter(|run| codex_app_server_trace_key(run) == trace_key)
        .cloned()
        .collect::<Vec<_>>();
    if matching.is_empty() {
        return Err(AppError::not_found("Codex App Server trace not found"));
    }
    matching.sort_by_key(|run| run.created_at);
    let summary = build_codex_app_server_trace_summary(&matching);
    let trace = summary
        .traces
        .into_iter()
        .find(|trace| trace.trace_key == trace_key)
        .ok_or_else(|| AppError::not_found("Codex App Server trace not found"))?;
    let evidence = codex_trace_evidence(&matching, events, audit_logs);
    let artifact_lineage = codex_trace_artifact_lineage(&matching, audit_logs);
    let matching_refs = matching.iter().collect::<Vec<_>>();
    let dashboard = build_codex_trace_dashboard(
        &matching_refs,
        &evidence,
        artifact_lineage.len(),
        trace.terminal,
    );
    let status_timeline = matching
        .iter()
        .map(|run| CodexAppServerStatusPoint {
            run_id: run.id,
            operation: run.operation.clone(),
            status: run.status.clone(),
            terminal: codex_turn_status_is_terminal(&run.status),
            created_at: run.created_at,
            error: run.error.clone(),
        })
        .collect::<Vec<_>>();
    let mut by_status = HashMap::new();
    let mut by_operation = HashMap::new();
    let mut command_ids = BTreeSet::new();
    let mut terminal_count = 0usize;
    let mut non_terminal_count = 0usize;
    for run in &matching {
        increment_count(&mut by_status, run.status.as_str());
        increment_count(&mut by_operation, run.operation.as_str());
        if let Some(command_id) = run.command_id.as_ref() {
            command_ids.insert(command_id.clone());
        }
        if codex_turn_status_is_terminal(&run.status) {
            terminal_count += 1;
        } else {
            non_terminal_count += 1;
        }
    }
    let errors = matching
        .iter()
        .filter_map(|run| run.error.clone())
        .collect::<Vec<_>>();
    let latest_response = matching
        .last()
        .map(|run| run.response.clone())
        .unwrap_or_else(|| json!({}));
    Ok(CodexAppServerTraceDetail {
        generated_at: Utc::now(),
        trace,
        runs: matching,
        status_timeline,
        by_status,
        by_operation,
        terminal_count,
        non_terminal_count,
        command_ids: command_ids.into_iter().collect(),
        errors,
        dashboard,
        evidence,
        artifact_lineage,
        latest_response,
    })
}

fn codex_app_server_trace_key(run: &CodexAppServerRun) -> String {
    run.turn_id
        .clone()
        .or_else(|| run.command_id.clone())
        .unwrap_or_else(|| format!("run:{}", run.id))
}

fn codex_run_status_failed(status: &str) -> bool {
    matches!(
        status.trim().to_ascii_lowercase().as_str(),
        "failed" | "poll_failed" | "cancelled" | "canceled" | "interrupted"
    )
}

async fn sync_codex_artifacts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<CodexArtifactSyncRequest>,
) -> Result<Json<CodexArtifactSyncResponse>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::Admin,
        "session",
        Some(input.session_id),
    )
    .await?;
    if input.artifacts.is_empty() {
        return Err(AppError::bad_request("at least one artifact is required"));
    }
    if input.artifacts.len() > 50 {
        return Err(AppError::bad_request(
            "Codex artifact sync accepts at most 50 artifacts per request",
        ));
    }
    state.get_session(input.session_id).await?;

    let mut artifacts = Vec::with_capacity(input.artifacts.len());
    for artifact_input in input.artifacts {
        let name = artifact_input.name.trim();
        if name.is_empty() {
            return Err(AppError::bad_request("artifact name is required"));
        }
        let artifact_type = artifact_input.artifact_type.trim();
        if artifact_type.is_empty() {
            return Err(AppError::bad_request("artifact_type is required"));
        }
        let path = normalize_codex_artifact_path(artifact_input.path.as_deref())?;
        let artifact = Artifact {
            id: Uuid::new_v4(),
            session_id: input.session_id,
            artifact_type: artifact_type.to_string(),
            name: name.to_string(),
            path,
            content: artifact_input.content,
            created_at: Utc::now(),
        };
        let artifact = state.insert_artifact(artifact).await?;
        state
            .append_event(
                "worker",
                Some(artifact.id),
                input.session_id,
                "artifact.created",
                json!({
                    "artifact_id": artifact.id,
                    "name": artifact.name,
                    "path": artifact.path,
                    "artifact_type": artifact.artifact_type,
                    "source": "codex_app_server",
                    "turn_id": input.turn_id,
                    "command_id": input.command_id,
                    "metadata": artifact_input.metadata,
                }),
            )
            .await?;
        state
            .append_audit_log(new_audit_log(
                Some(input.session_id),
                "worker",
                Some(artifact.id),
                "codex_app_server.artifact_synced",
                "artifact",
                Some(artifact.id),
                json!({
                    "name": artifact.name,
                    "path": artifact.path,
                    "artifact_type": artifact.artifact_type,
                    "turn_id": input.turn_id,
                    "command_id": input.command_id,
                }),
            ))
            .await?;
        artifacts.push(artifact);
    }

    Ok(Json(CodexArtifactSyncResponse {
        session_id: input.session_id,
        turn_id: input.turn_id,
        command_id: input.command_id,
        artifact_count: artifacts.len(),
        artifacts,
    }))
}

async fn sync_remote_computer_artifacts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<RemoteComputerArtifactSyncRequest>,
) -> Result<Json<RemoteComputerArtifactSyncResponse>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "remote_computer",
        Some(input.remote_computer_id),
    )
    .await?;
    if input.artifacts.is_empty() {
        return Err(AppError::bad_request("at least one artifact is required"));
    }
    if input.artifacts.len() > 50 {
        return Err(AppError::bad_request(
            "Remote Computer artifact sync accepts at most 50 artifacts per request",
        ));
    }
    state.get_session(input.session_id).await?;
    let remote_computer = state
        .list_remote_computers()
        .await?
        .into_iter()
        .find(|computer| computer.id == input.remote_computer_id)
        .ok_or_else(|| AppError::not_found("Remote computer not found"))?;
    if let Some(assignment_id) = input.assignment_id {
        let assignment = state
            .list_remote_computer_job_assignments()
            .await?
            .into_iter()
            .find(|assignment| assignment.id == assignment_id)
            .ok_or_else(|| AppError::not_found("Remote computer job assignment not found"))?;
        if assignment.remote_computer_id != input.remote_computer_id
            || assignment.session_id != input.session_id
        {
            return Err(AppError::bad_request(
                "Remote Computer artifact sync assignment does not match session or remote computer",
            ));
        }
    }

    let mut artifacts = Vec::with_capacity(input.artifacts.len());
    for artifact_input in input.artifacts {
        let name = artifact_input.name.trim();
        if name.is_empty() {
            return Err(AppError::bad_request("artifact name is required"));
        }
        let artifact_type = artifact_input.artifact_type.trim();
        if artifact_type.is_empty() {
            return Err(AppError::bad_request("artifact_type is required"));
        }
        let path = normalize_codex_artifact_path(artifact_input.path.as_deref())?;
        let artifact = Artifact {
            id: Uuid::new_v4(),
            session_id: input.session_id,
            artifact_type: artifact_type.to_string(),
            name: name.to_string(),
            path,
            content: artifact_input.content,
            created_at: Utc::now(),
        };
        let artifact = state.insert_artifact(artifact).await?;
        state
            .append_event(
                "worker",
                Some(artifact.id),
                input.session_id,
                "artifact.created",
                json!({
                    "artifact_id": artifact.id,
                    "name": artifact.name,
                    "path": artifact.path,
                    "artifact_type": artifact.artifact_type,
                    "source": "remote_computer",
                    "remote_computer_id": remote_computer.id,
                    "assignment_id": input.assignment_id,
                    "workspace_path": remote_computer.workspace_path,
                    "metadata": artifact_input.metadata,
                }),
            )
            .await?;
        state
            .append_audit_log(new_audit_log(
                Some(input.session_id),
                "worker",
                Some(artifact.id),
                "remote_computer.artifact_synced",
                "artifact",
                Some(artifact.id),
                json!({
                    "name": artifact.name,
                    "path": artifact.path,
                    "artifact_type": artifact.artifact_type,
                    "remote_computer_id": remote_computer.id,
                    "assignment_id": input.assignment_id,
                }),
            ))
            .await?;
        artifacts.push(artifact);
    }

    Ok(Json(RemoteComputerArtifactSyncResponse {
        session_id: input.session_id,
        remote_computer_id: input.remote_computer_id,
        assignment_id: input.assignment_id,
        artifact_count: artifacts.len(),
        artifacts,
    }))
}

async fn discover_remote_computer_artifacts(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<RemoteComputerArtifactDiscoverRequest>,
) -> Result<Json<RemoteComputerArtifactSyncResponse>, AppError> {
    authorize_request(
        &state,
        &headers,
        Permission::SessionsRun,
        "remote_computer",
        Some(input.remote_computer_id),
    )
    .await?;
    if input.max_files == 0 || input.max_files > 50 {
        return Err(AppError::bad_request(
            "Remote Computer artifact discovery accepts between 1 and 50 files per request",
        ));
    }
    state.get_session(input.session_id).await?;
    let remote_computer = state
        .list_remote_computers()
        .await?
        .into_iter()
        .find(|computer| computer.id == input.remote_computer_id)
        .ok_or_else(|| AppError::not_found("Remote computer not found"))?;
    if let Some(assignment_id) = input.assignment_id {
        let assignment = state
            .list_remote_computer_job_assignments()
            .await?
            .into_iter()
            .find(|assignment| assignment.id == assignment_id)
            .ok_or_else(|| AppError::not_found("Remote computer job assignment not found"))?;
        if assignment.remote_computer_id != input.remote_computer_id
            || assignment.session_id != input.session_id
        {
            return Err(AppError::bad_request(
                "Remote Computer artifact discovery assignment does not match session or remote computer",
            ));
        }
    }

    let artifact_dir = normalize_remote_computer_artifact_dir(&input.artifact_dir)?;
    let workspace_path = PathBuf::from(&remote_computer.workspace_path);
    let discovery_root = workspace_path.join(&artifact_dir);
    let root_metadata = tokio::fs::metadata(&discovery_root)
        .await
        .map_err(|error| {
            if error.kind() == std::io::ErrorKind::NotFound {
                AppError::not_found("Remote Computer artifact discovery directory not found")
            } else {
                AppError::from(error)
            }
        })?;
    if !root_metadata.is_dir() {
        return Err(AppError::bad_request(
            "Remote Computer artifact discovery path must be a directory",
        ));
    }

    let discovered_files =
        discover_artifact_files(&discovery_root, input.max_files, 1_048_576).await?;
    if discovered_files.is_empty() {
        return Err(AppError::bad_request(
            "Remote Computer artifact discovery found no files",
        ));
    }

    let mut artifacts = Vec::with_capacity(discovered_files.len());
    for discovered in discovered_files {
        let relative_path = discovered
            .path
            .strip_prefix(&workspace_path)
            .unwrap_or(&discovered.path)
            .to_string_lossy()
            .replace('\\', "/");
        let name = discovered
            .path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("artifact")
            .to_string();
        let artifact = Artifact {
            id: Uuid::new_v4(),
            session_id: input.session_id,
            artifact_type: artifact_type_from_path(&discovered.path),
            name,
            path: Some(relative_path.clone()),
            content: json!({
                "text": discovered.content,
                "bytes": discovered.bytes,
                "source": "remote_computer_artifact_discovery",
            }),
            created_at: Utc::now(),
        };
        let artifact = state.insert_artifact(artifact).await?;
        state
            .append_event(
                "worker",
                Some(artifact.id),
                input.session_id,
                "artifact.created",
                json!({
                    "artifact_id": artifact.id,
                    "name": artifact.name,
                    "path": artifact.path,
                    "artifact_type": artifact.artifact_type,
                    "source": "remote_computer_artifact_discovery",
                    "remote_computer_id": remote_computer.id,
                    "assignment_id": input.assignment_id,
                    "workspace_path": remote_computer.workspace_path,
                    "artifact_dir": artifact_dir,
                }),
            )
            .await?;
        state
            .append_audit_log(new_audit_log(
                Some(input.session_id),
                "worker",
                Some(artifact.id),
                "remote_computer.artifact_discovered",
                "artifact",
                Some(artifact.id),
                json!({
                    "name": artifact.name,
                    "path": artifact.path,
                    "artifact_type": artifact.artifact_type,
                    "remote_computer_id": remote_computer.id,
                    "assignment_id": input.assignment_id,
                    "artifact_dir": artifact_dir,
                }),
            ))
            .await?;
        artifacts.push(artifact);
    }

    Ok(Json(RemoteComputerArtifactSyncResponse {
        session_id: input.session_id,
        remote_computer_id: input.remote_computer_id,
        assignment_id: input.assignment_id,
        artifact_count: artifacts.len(),
        artifacts,
    }))
}

fn normalize_codex_artifact_path(path: Option<&str>) -> Result<Option<String>, AppError> {
    let Some(path) = path.map(str::trim).filter(|path| !path.is_empty()) else {
        return Ok(None);
    };
    if path.starts_with('/') || path.split('/').any(|segment| segment == "..") {
        return Err(AppError::bad_request(
            "Codex artifact path must be relative and stay inside the session workspace",
        ));
    }
    Ok(Some(path.to_string()))
}

fn normalize_remote_computer_artifact_dir(path: &str) -> Result<String, AppError> {
    let path = path.trim();
    let path = if path.is_empty() { "artifacts" } else { path };
    if path.starts_with('/') || path.split('/').any(|segment| segment == "..") {
        return Err(AppError::bad_request(
            "Remote Computer artifact discovery path must be relative and stay inside the workspace",
        ));
    }
    Ok(path.to_string())
}

struct DiscoveredArtifactFile {
    path: PathBuf,
    bytes: u64,
    content: String,
}

async fn discover_artifact_files(
    root: &PathBuf,
    max_files: usize,
    max_file_bytes: u64,
) -> Result<Vec<DiscoveredArtifactFile>, AppError> {
    let mut files = Vec::new();
    let mut directories = vec![root.clone()];
    let mut visited_directories = 0_usize;
    while let Some(directory) = directories.pop() {
        visited_directories += 1;
        if visited_directories > 1000 {
            return Err(AppError::bad_request(
                "Remote Computer artifact discovery exceeded directory traversal limit",
            ));
        }
        let mut read_dir = tokio::fs::read_dir(&directory).await?;
        let mut entries = Vec::new();
        while let Some(entry) = read_dir.next_entry().await? {
            entries.push(entry.path());
        }
        entries.sort();
        for entry_path in entries.into_iter().rev() {
            let metadata = tokio::fs::symlink_metadata(&entry_path).await?;
            if metadata.is_dir() {
                directories.push(entry_path);
                continue;
            }
            if !metadata.is_file() {
                continue;
            }
            if metadata.len() > max_file_bytes {
                return Err(AppError::bad_request(format!(
                    "Remote Computer artifact {} exceeds 1 MiB discovery limit",
                    entry_path.display()
                )));
            }
            let bytes = tokio::fs::read(&entry_path).await?;
            let content = match String::from_utf8(bytes) {
                Ok(content) => content,
                Err(error) => String::from_utf8_lossy(error.as_bytes()).to_string(),
            };
            files.push(DiscoveredArtifactFile {
                path: entry_path,
                bytes: metadata.len(),
                content,
            });
            if files.len() >= max_files {
                return Ok(files);
            }
        }
    }
    files.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(files)
}

fn artifact_type_from_path(path: &PathBuf) -> String {
    match path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase()
        .as_str()
    {
        "md" | "markdown" => "markdown",
        "json" => "json",
        "sql" => "sql",
        "csv" => "csv",
        "log" => "log",
        "py" | "sh" | "rs" | "ts" | "tsx" | "js" | "jsx" => "script",
        _ => "file",
    }
    .to_string()
}

fn codex_app_server_config(state: &AppState) -> Result<&CodexAppServerConfig, AppError> {
    state
        .codex_app_server_config
        .as_ref()
        .ok_or_else(|| AppError::bad_request("Codex App Server is not configured"))
}

async fn secret_provider_health_from_lookup<F>(lookup: F) -> SecretProviderHealth
where
    F: Fn(&str) -> Option<String>,
{
    let checked_at = Utc::now();
    let kind = match SecretProviderKind::from_lookup(&lookup) {
        Ok(kind) => kind,
        Err(error) => {
            return SecretProviderHealth {
                provider_kind: "invalid".to_string(),
                healthy: false,
                status: "misconfigured".to_string(),
                issues: vec![error.message],
                checks: json!({}),
                checked_at,
            };
        }
    };
    match kind {
        SecretProviderKind::Reserved => SecretProviderHealth {
            provider_kind: "reserved".to_string(),
            healthy: false,
            status: "reserved".to_string(),
            issues: vec![
                "secret reads are disabled until MANDOFORGE_SECRET_PROVIDER=vault is configured"
                    .to_string(),
            ],
            checks: json!({"provider": "reserved"}),
            checked_at,
        },
        SecretProviderKind::Vault => match SecretProviderConfig::from_lookup(&lookup) {
            Ok(config) => match VaultSecretProvider::new() {
                Ok(provider) => match provider.health_check(&config).await {
                    Ok(()) => SecretProviderHealth {
                        provider_kind: "vault".to_string(),
                        healthy: true,
                        status: "healthy".to_string(),
                        issues: vec![],
                        checks: json!({
                            "vault_addr_configured": !config.vault_addr.trim().is_empty(),
                            "mount": config.mount,
                            "namespace_configured": config.namespace.is_some(),
                            "token_configured": config.token.is_some(),
                        }),
                        checked_at,
                    },
                    Err(error) => SecretProviderHealth {
                        provider_kind: "vault".to_string(),
                        healthy: false,
                        status: "unhealthy".to_string(),
                        issues: vec![error.message],
                        checks: json!({
                            "vault_addr_configured": !config.vault_addr.trim().is_empty(),
                            "mount": config.mount,
                            "namespace_configured": config.namespace.is_some(),
                            "token_configured": config.token.is_some(),
                        }),
                        checked_at,
                    },
                },
                Err(error) => SecretProviderHealth {
                    provider_kind: "vault".to_string(),
                    healthy: false,
                    status: "client_error".to_string(),
                    issues: vec![error.message],
                    checks: json!({}),
                    checked_at,
                },
            },
            Err(error) => SecretProviderHealth {
                provider_kind: "vault".to_string(),
                healthy: false,
                status: "misconfigured".to_string(),
                issues: vec![error.message],
                checks: json!({"provider": "vault"}),
                checked_at,
            },
        },
    }
}

fn build_vault_readiness_report<F>(
    secret_provider: SecretProviderHealth,
    secret_records: &[SecretRecord],
    providers: &[ProviderRecord],
    mcp_servers: &[McpServerRecord],
    audit_logs: &[AuditLog],
    lookup: F,
) -> VaultReadinessReport
where
    F: Fn(&str) -> Option<String>,
{
    let generated_at = Utc::now();
    let registered_refs: BTreeSet<String> = secret_records.iter().map(secret_record_ref).collect();
    let mut checks = Vec::new();
    let mut attention_items = Vec::new();
    let mut unresolved_refs = BTreeSet::new();
    let mut provider_ref_count = 0;
    let mut eval_judge_secret_ref_count = 0;
    let mut mcp_secret_ref_count = 0;

    let mut provider_blockers = Vec::new();
    let mut provider_warnings = Vec::new();
    let mut provider_recommendations = Vec::new();
    if !secret_provider.healthy {
        provider_blockers.push(format!(
            "secret provider is {}: {}",
            secret_provider.status,
            secret_provider.issues.join("; ")
        ));
        provider_recommendations
            .push("configure MANDOFORGE_SECRET_PROVIDER=vault and verify Vault health".to_string());
    }
    if secret_provider.provider_kind == "reserved" {
        provider_blockers
            .push("reserved secret provider cannot read production secrets".to_string());
    }
    if secret_provider.provider_kind == "vault"
        && secret_provider
            .checks
            .get("token_configured")
            .and_then(Value::as_bool)
            == Some(false)
    {
        provider_blockers.push("Vault token is not configured".to_string());
    }
    if secret_records.is_empty() {
        provider_warnings.push("no secret refs are registered in the catalog".to_string());
        provider_recommendations
            .push("register provider, MCP, and judge secret refs before pilot rollout".to_string());
    }
    checks.push(VaultReadinessCheck {
        resource_type: "secret_provider".to_string(),
        resource_id: None,
        resource_name: secret_provider.provider_kind.clone(),
        status: vault_check_status(&provider_blockers, &provider_warnings),
        secret_refs: vec![],
        blockers: provider_blockers,
        warnings: provider_warnings,
        recommendations: provider_recommendations,
    });

    let kms = kms_readiness_from_lookup(&lookup);
    checks.push(VaultReadinessCheck {
        resource_type: "kms".to_string(),
        resource_id: None,
        resource_name: kms.provider.clone(),
        status: if kms.status == "ready" {
            "passed".to_string()
        } else {
            "failed".to_string()
        },
        secret_refs: vec![],
        blockers: kms.issues.clone(),
        warnings: vec![],
        recommendations: if kms.status == "ready" {
            vec![]
        } else {
            vec![
                "configure MANDOFORGE_KMS_PROVIDER, MANDOFORGE_KMS_KEY_ID, and MANDOFORGE_KMS_ROTATION_POLICY".to_string(),
            ]
        },
    });

    let stale_cutoff = generated_at - ChronoDuration::days(90);
    for record in secret_records {
        let mut blockers = Vec::new();
        let mut warnings = Vec::new();
        let mut recommendations = Vec::new();
        if record.status != "active" {
            blockers.push(format!("secret record status is {}", record.status));
            recommendations.push("reactivate or rotate this secret ref before rollout".to_string());
        }
        if record.updated_at < stale_cutoff {
            warnings.push("secret ref has not rotated in more than 90 days".to_string());
            recommendations
                .push("rotate this secret ref and verify downstream consumers".to_string());
        }
        checks.push(VaultReadinessCheck {
            resource_type: "secret_record".to_string(),
            resource_id: Some(record.id),
            resource_name: record.name.clone(),
            status: vault_check_status(&blockers, &warnings),
            secret_refs: vec![secret_record_ref(record)],
            blockers,
            warnings,
            recommendations,
        });
    }

    for provider in providers {
        let Some(secret_ref) = provider_api_key_ref(provider) else {
            if provider_requires_api_key(&provider.provider_type) {
                let has_env = provider
                    .config
                    .get("api_key_env")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .is_some_and(|value| !value.is_empty());
                let mut blockers = Vec::new();
                let mut warnings = Vec::new();
                let mut recommendations = Vec::new();
                if has_env {
                    warnings.push("provider uses env credential instead of Vault ref".to_string());
                    recommendations
                        .push("rotate provider credential to vault:path#key".to_string());
                } else {
                    blockers.push("provider requires api_key_ref or api_key_env".to_string());
                    recommendations.push(
                        "bind provider credential through a registered Vault ref".to_string(),
                    );
                }
                checks.push(VaultReadinessCheck {
                    resource_type: "provider".to_string(),
                    resource_id: Some(provider.id),
                    resource_name: provider.name.clone(),
                    status: vault_check_status(&blockers, &warnings),
                    secret_refs: vec![],
                    blockers,
                    warnings,
                    recommendations,
                });
            }
            continue;
        };
        if provider.provider_type == "eval_judge" {
            eval_judge_secret_ref_count += 1;
        } else {
            provider_ref_count += 1;
        }
        let mut blockers = Vec::new();
        let mut recommendations = Vec::new();
        if !registered_refs.contains(&secret_ref) {
            unresolved_refs.insert(secret_ref.clone());
            blockers.push("api_key_ref is not registered in the secret catalog".to_string());
            recommendations.push("create a matching /api/vault/secrets catalog entry".to_string());
        }
        checks.push(VaultReadinessCheck {
            resource_type: if provider.provider_type == "eval_judge" {
                "eval_judge_profile".to_string()
            } else {
                "provider".to_string()
            },
            resource_id: Some(provider.id),
            resource_name: provider.name.clone(),
            status: vault_check_status(&blockers, &[]),
            secret_refs: vec![secret_ref],
            blockers,
            warnings: vec![],
            recommendations,
        });
    }

    for server in mcp_servers {
        let secret_refs = mcp_config_secret_refs(&server.config);
        if secret_refs.is_empty() {
            continue;
        }
        mcp_secret_ref_count += secret_refs.len();
        let mut blockers = Vec::new();
        let mut recommendations = Vec::new();
        for secret_ref in &secret_refs {
            if !registered_refs.contains(secret_ref) {
                unresolved_refs.insert(secret_ref.clone());
                blockers.push(format!(
                    "{secret_ref} is not registered in the secret catalog"
                ));
            }
        }
        if !blockers.is_empty() {
            recommendations.push(
                "register every MCP connector secret ref before enabling the connector".to_string(),
            );
        }
        checks.push(VaultReadinessCheck {
            resource_type: "mcp_server".to_string(),
            resource_id: Some(server.id),
            resource_name: server.name.clone(),
            status: vault_check_status(&blockers, &[]),
            secret_refs,
            blockers,
            warnings: vec![],
            recommendations,
        });
    }

    for check in &checks {
        for blocker in &check.blockers {
            attention_items.push(VaultReadinessAttentionItem {
                resource_type: check.resource_type.clone(),
                resource_id: check.resource_id,
                resource_name: check.resource_name.clone(),
                kind: "blocker".to_string(),
                severity: "critical".to_string(),
                message: blocker.clone(),
            });
        }
        for warning in &check.warnings {
            attention_items.push(VaultReadinessAttentionItem {
                resource_type: check.resource_type.clone(),
                resource_id: check.resource_id,
                resource_name: check.resource_name.clone(),
                kind: "warning".to_string(),
                severity: "warning".to_string(),
                message: warning.clone(),
            });
        }
    }

    let stale_rotation_count = secret_records
        .iter()
        .filter(|record| record.updated_at < stale_cutoff)
        .count();
    let production_rotation = build_vault_production_rotation_readiness(
        &secret_provider,
        &kms,
        unresolved_refs.len(),
        stale_rotation_count,
        audit_logs,
        generated_at,
    );
    let production_recovery = build_vault_kms_recovery_readiness(
        &kms,
        audit_logs,
        generated_at,
        vault_kms_recovery_controller_required(&lookup),
        vault_kms_recovery_controller_configured(&lookup),
    );
    if production_rotation.production_blocked {
        attention_items.push(VaultReadinessAttentionItem {
            resource_type: "vault".to_string(),
            resource_id: None,
            resource_name: "production_rotation".to_string(),
            kind: "production_rotation_blocked".to_string(),
            severity: "critical".to_string(),
            message: production_rotation.message.clone(),
        });
    }
    if production_recovery.production_blocked {
        attention_items.push(VaultReadinessAttentionItem {
            resource_type: "vault".to_string(),
            resource_id: None,
            resource_name: "kms_recovery".to_string(),
            kind: "production_recovery_blocked".to_string(),
            severity: "critical".to_string(),
            message: production_recovery.message.clone(),
        });
    }

    let failed_count = checks
        .iter()
        .filter(|check| check.status == "failed")
        .count();
    let warning_count = checks
        .iter()
        .filter(|check| check.status == "warning")
        .count();
    let status = if failed_count > 0 {
        "failed"
    } else if warning_count > 0 {
        "warning"
    } else {
        "passed"
    }
    .to_string();

    VaultReadinessReport {
        generated_at,
        status,
        secret_provider,
        kms,
        production_rotation,
        production_recovery,
        secret_record_count: secret_records.len(),
        active_secret_record_count: secret_records
            .iter()
            .filter(|record| record.status == "active")
            .count(),
        provider_ref_count,
        mcp_secret_ref_count,
        eval_judge_secret_ref_count,
        unresolved_ref_count: unresolved_refs.len(),
        stale_rotation_count,
        checks,
        attention_items,
    }
}

fn build_vault_production_rotation_readiness(
    secret_provider: &SecretProviderHealth,
    kms: &VaultKmsReadiness,
    unresolved_ref_count: usize,
    stale_rotation_count: usize,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
) -> VaultProductionRotationReadiness {
    let latest_rotation_run = audit_logs
        .iter()
        .filter(|log| log.action == "vault.kms_rotation_run")
        .max_by_key(|log| log.created_at);
    let latest_rotation_run_status = latest_rotation_run
        .and_then(|log| log.details.get("status").and_then(Value::as_str))
        .map(ToString::to_string);
    let latest_rotation_validated = latest_rotation_run.is_some_and(|log| {
        latest_rotation_run_status.as_deref() == Some("validated")
            && (generated_at - log.created_at).num_hours() < 30
    });
    let vault_healthy = secret_provider.healthy && secret_provider.provider_kind == "vault";
    let kms_ready = kms.status == "ready" && kms.configured;
    let unresolved_refs_clear = unresolved_ref_count == 0;
    let stale_rotations_clear = stale_rotation_count == 0;
    let mut blocking_reasons = Vec::new();

    if !vault_healthy {
        blocking_reasons.push("Vault secret provider is not healthy and selected".to_string());
    }
    if !kms_ready {
        blocking_reasons
            .push("external KMS/HSM readiness is not configured and validated".to_string());
    }
    if !unresolved_refs_clear {
        blocking_reasons
            .push("registered consumers reference secrets missing from the catalog".to_string());
    }
    if !stale_rotations_clear {
        blocking_reasons
            .push("one or more active secret refs are past the rotation window".to_string());
    }
    if !latest_rotation_validated {
        blocking_reasons.push("no recent validated KMS rotation gate run exists".to_string());
    }

    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Vault production rotation is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Vault production rotation has healthy Vault, ready KMS/HSM, resolved refs, fresh rotations, and recent validated gate evidence".to_string()
    };

    VaultProductionRotationReadiness {
        status,
        production_blocked,
        vault_healthy,
        kms_ready,
        unresolved_refs_clear,
        stale_rotations_clear,
        latest_rotation_validated,
        latest_rotation_run_at: latest_rotation_run.map(|log| log.created_at),
        latest_rotation_run_status,
        blocking_reasons,
        message,
    }
}

fn build_vault_kms_recovery_readiness(
    kms: &VaultKmsReadiness,
    audit_logs: &[AuditLog],
    generated_at: DateTime<Utc>,
    controller_required: bool,
    controller_configured: bool,
) -> VaultKmsRecoveryReadiness {
    let latest_rotation_run = audit_logs
        .iter()
        .filter(|log| log.action == "vault.kms_rotation_run")
        .max_by_key(|log| log.created_at);
    let latest_rotation_validated = latest_rotation_run.is_some_and(|log| {
        log.details.get("status").and_then(Value::as_str) == Some("validated")
            && (generated_at - log.created_at).num_hours() < 30
    });
    let latest_recovery = audit_logs
        .iter()
        .filter(|log| log.action == "vault.kms_recovery_validation")
        .max_by_key(|log| log.created_at);
    let latest_recovery_status = latest_recovery
        .and_then(|log| log.details.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_status = latest_recovery
        .and_then(|log| log.details.get("controller_execution"))
        .and_then(|execution| execution.get("status"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_execution =
        latest_recovery.and_then(|log| log.details.get("controller_execution"));
    let latest_controller_backend_kind = latest_controller_execution
        .and_then(|execution| execution.get("backend_kind"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_environment = latest_controller_execution
        .and_then(|execution| execution.get("environment"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_backend_id = latest_controller_execution
        .and_then(|execution| execution.get("backend_id"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_key_id = latest_controller_execution
        .and_then(|execution| execution.get("key_id"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_hsm_provider = latest_controller_execution
        .and_then(|execution| execution.get("hsm_provider"))
        .and_then(Value::as_str)
        .map(str::to_string);
    let latest_controller_age_hours = latest_recovery
        .filter(|_| latest_controller_status.is_some())
        .map(|log| (generated_at - log.created_at).num_hours());
    let controller_evidence_fresh =
        latest_controller_age_hours.is_some_and(|age_hours| age_hours < 24);
    let latest_controller_production_backend =
        latest_controller_execution.is_some_and(kms_controller_execution_is_production_backend);
    let latest_controller_validated = latest_recovery_status.as_deref() == Some("validated")
        && latest_controller_status.as_deref() == Some("validated")
        && latest_controller_production_backend;
    let mut blocking_reasons = Vec::new();
    if kms.status != "ready" || !kms.configured {
        blocking_reasons
            .push("external KMS/HSM readiness is not configured and validated".to_string());
    }
    if !latest_rotation_validated {
        blocking_reasons.push(
            "validated KMS rotation evidence is required before recovery validation".to_string(),
        );
    }
    if latest_recovery_status.as_deref() != Some("validated") {
        blocking_reasons.push("no validated KMS recovery drill evidence exists".to_string());
    }
    if controller_required && !controller_configured {
        blocking_reasons
            .push("vault KMS recovery controller is required but not configured".to_string());
    }
    if controller_required
        && controller_configured
        && latest_controller_status.as_deref() != Some("validated")
    {
        blocking_reasons
            .push("vault KMS recovery controller evidence is missing or not validated".to_string());
    }
    if controller_required
        && latest_controller_status.as_deref() == Some("validated")
        && !latest_controller_production_backend
    {
        blocking_reasons.push(
            "vault KMS recovery controller did not identify a real production KMS/HSM backend"
                .to_string(),
        );
    }
    if controller_required && latest_controller_validated && !controller_evidence_fresh {
        blocking_reasons.push("vault KMS recovery controller evidence is stale".to_string());
    }
    let production_blocked = !blocking_reasons.is_empty();
    let status = if production_blocked {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let message = if production_blocked {
        format!(
            "Vault KMS recovery readiness is blocked: {}",
            blocking_reasons.join("; ")
        )
    } else {
        "Vault KMS recovery has recent rotation evidence and validated recovery-controller drill evidence".to_string()
    };
    VaultKmsRecoveryReadiness {
        status,
        production_blocked,
        controller_required,
        controller_configured,
        latest_recovery_at: latest_recovery.map(|log| log.created_at),
        latest_recovery_status,
        latest_controller_status,
        latest_controller_age_hours,
        controller_evidence_fresh,
        latest_controller_validated,
        latest_controller_production_backend,
        latest_controller_backend_kind,
        latest_controller_environment,
        latest_controller_backend_id,
        latest_controller_key_id,
        latest_controller_hsm_provider,
        latest_rotation_validated,
        blocking_reasons,
        message,
    }
}

fn vault_kms_recovery_controller_required<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_KMS_RECOVERY_CONTROLLER_REQUIRED")
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        })
        .unwrap_or(false)
}

fn vault_kms_recovery_controller_configured<F>(lookup: &F) -> bool
where
    F: Fn(&str) -> Option<String>,
{
    lookup("MANDOFORGE_KMS_RECOVERY_CONTROLLER_URL")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false)
}

async fn execute_vault_kms_recovery_controller<F>(
    lookup: &F,
    subject: &str,
    checked_at: DateTime<Utc>,
    kms: &VaultKmsReadiness,
    secret_records: &[SecretRecord],
    readiness: &VaultKmsRecoveryReadiness,
) -> Result<Value, AppError>
where
    F: Fn(&str) -> Option<String>,
{
    let endpoint = lookup("MANDOFORGE_KMS_RECOVERY_CONTROLLER_URL")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            AppError::bad_request("MANDOFORGE_KMS_RECOVERY_CONTROLLER_URL is required")
        })?;
    let timeout_seconds = lookup("MANDOFORGE_KMS_RECOVERY_TIMEOUT_SECONDS")
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| (1..=120).contains(seconds))
        .unwrap_or(15);
    let token = lookup("MANDOFORGE_KMS_RECOVERY_CONTROLLER_TOKEN")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    let secret_refs = secret_records
        .iter()
        .map(|record| {
            json!({
                "id": record.id,
                "name": record.name,
                "scope_type": record.scope_type,
                "scope_id": record.scope_id,
                "path": record.path,
                "key": record.key,
                "status": record.status,
                "version": record.version,
                "updated_at": record.updated_at,
            })
        })
        .collect::<Vec<_>>();
    let payload = json!({
        "type": "mandoforge.kms_recovery_validation",
        "subject": subject,
        "checked_at": checked_at,
        "kms": {
            "provider": kms.provider,
            "status": kms.status,
            "key_id_configured": kms.key_id_configured,
            "rotation_policy_configured": kms.rotation_policy_configured,
            "endpoint_configured": kms.endpoint_configured,
            "validation_mode": kms.validation_mode,
        },
        "readiness": {
            "status": readiness.status,
            "production_blocked": readiness.production_blocked,
            "latest_rotation_validated": readiness.latest_rotation_validated,
            "blocking_reasons": readiness.blocking_reasons,
        },
        "secret_refs": secret_refs,
    });
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .build()?;
    let mut request = client.post(endpoint).json(&payload);
    if let Some(token) = token {
        request = request.bearer_auth(token);
    }
    let response = request.send().await?;
    let http_status = response.status();
    let body = response.json::<Value>().await.unwrap_or_else(|_| json!({}));
    if !http_status.is_success() {
        return Err(AppError::bad_request(format!(
            "vault KMS recovery controller failed with status {http_status}"
        )));
    }
    let provider_status = body
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("validated");
    let validated = matches!(provider_status, "validated" | "success" | "ok" | "healthy");
    Ok(json!({
        "attempted": true,
        "status": if validated { "validated" } else { "blocked" },
        "http_status": http_status.as_u16(),
        "provider_status": provider_status,
        "recovery_id": body.get("recovery_id").and_then(Value::as_str),
        "backend_kind": body.get("backend_kind").and_then(Value::as_str),
        "backend_id": body.get("backend_id").and_then(Value::as_str),
        "key_id": body.get("key_id").and_then(Value::as_str),
        "environment": body.get("environment").and_then(Value::as_str),
        "hsm_provider": body.get("hsm_provider").and_then(Value::as_str),
        "recovery_target_kind": body.get("recovery_target_kind").and_then(Value::as_str),
        "message": body.get("message").and_then(Value::as_str),
        "steps": body.get("steps").cloned().unwrap_or_else(|| json!([])),
    }))
}

fn normalized_kms_kind(value: &str) -> String {
    value.trim().to_ascii_lowercase().replace('-', "_")
}

fn is_production_kms_provider(value: &str) -> bool {
    matches!(
        normalized_kms_kind(value).as_str(),
        "external"
            | "external_kms"
            | "aws_kms"
            | "gcp_kms"
            | "azure_key_vault"
            | "hashicorp_vault_transit"
            | "vault_transit"
            | "hsm"
            | "cloudhsm"
            | "pkcs11_hsm"
    )
}

fn is_production_kms_backend_kind(value: Option<&str>) -> bool {
    value.is_some_and(|value| {
        matches!(
            normalized_kms_kind(value).as_str(),
            "external_kms"
                | "aws_kms"
                | "gcp_kms"
                | "azure_key_vault"
                | "hashicorp_vault_transit"
                | "vault_transit"
                | "hsm"
                | "cloudhsm"
                | "pkcs11_hsm"
        )
    })
}

fn is_production_kms_environment(value: Option<&str>) -> bool {
    matches!(value, Some("production" | "prod"))
}

fn kms_controller_execution_is_production_backend(execution: &Value) -> bool {
    let backend_id_present = execution
        .get("backend_id")
        .and_then(Value::as_str)
        .is_some_and(|value| !value.trim().is_empty());
    let key_id_present = execution
        .get("key_id")
        .and_then(Value::as_str)
        .is_some_and(|value| !value.trim().is_empty());
    is_production_kms_backend_kind(execution.get("backend_kind").and_then(Value::as_str))
        && is_production_kms_environment(execution.get("environment").and_then(Value::as_str))
        && backend_id_present
        && key_id_present
}

fn kms_readiness_from_lookup<F>(lookup: &F) -> VaultKmsReadiness
where
    F: Fn(&str) -> Option<String>,
{
    let provider = lookup("MANDOFORGE_KMS_PROVIDER")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "reserved".to_string());
    let key_id_configured = lookup("MANDOFORGE_KMS_KEY_ID")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);
    let rotation_policy_configured = lookup("MANDOFORGE_KMS_ROTATION_POLICY")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);
    let endpoint_configured = lookup("MANDOFORGE_KMS_ENDPOINT")
        .map(|value| !value.trim().is_empty())
        .unwrap_or(false);
    let validation_mode = lookup("MANDOFORGE_KMS_VALIDATION_MODE")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "health-check".to_string());
    let production_provider = is_production_kms_provider(&provider);
    let external_validation = validation_mode.trim().eq_ignore_ascii_case("external");
    let configured = provider != "reserved"
        && production_provider
        && key_id_configured
        && rotation_policy_configured
        && endpoint_configured
        && external_validation;
    let mut issues = Vec::new();
    if provider == "reserved" {
        issues.push("external KMS/HSM provider is not configured".to_string());
    } else if !production_provider {
        issues.push(format!(
            "KMS/HSM provider is not a production backend: {provider}"
        ));
    }
    if !key_id_configured {
        issues.push("MANDOFORGE_KMS_KEY_ID is not configured".to_string());
    }
    if !rotation_policy_configured {
        issues.push("MANDOFORGE_KMS_ROTATION_POLICY is not configured".to_string());
    }
    if !endpoint_configured {
        issues.push(
            "MANDOFORGE_KMS_ENDPOINT is not configured for external KMS validation".to_string(),
        );
    }
    if !external_validation {
        issues.push(
            "MANDOFORGE_KMS_VALIDATION_MODE must be external for production evidence".to_string(),
        );
    }
    VaultKmsReadiness {
        provider,
        status: if configured { "ready" } else { "reserved" }.to_string(),
        configured,
        key_id_configured,
        rotation_policy_configured,
        endpoint_configured,
        validation_mode,
        issues,
    }
}

fn vault_check_status(blockers: &[String], warnings: &[String]) -> String {
    if !blockers.is_empty() {
        "failed"
    } else if !warnings.is_empty() {
        "warning"
    } else {
        "passed"
    }
    .to_string()
}

fn secret_record_ref(record: &SecretRecord) -> String {
    format!("vault:{}#{}", record.path, record.key)
}

fn provider_api_key_ref(provider: &ProviderRecord) -> Option<String> {
    provider
        .config
        .get("api_key_ref")
        .and_then(Value::as_str)
        .and_then(|value| normalize_provider_api_key_ref(value).ok())
}

async fn update_provider_status(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<UpdateProviderStatus>,
) -> Result<Json<ProviderRecord>, AppError> {
    let principal = principal_from_request(&state, &headers).await?;
    let request = AuthorizationRequest {
        tenant_id: state.current_tenant_id(),
        permission: Permission::Admin,
        resource_type: "provider".to_string(),
        resource_id: Some(id),
    };
    state.authorizer.authorize(&principal, &request).await?;
    enforce_resource_scope(&state, &principal, &request).await?;
    let status = normalize_provider_status(&input.status)?;
    if !input.emergency {
        return Err(AppError::bad_request(
            "direct provider status changes require emergency=true; use status approval for normal changes",
        ));
    }
    let reason = optional_trimmed(input.reason.as_deref()).ok_or_else(|| {
        AppError::bad_request("direct provider status changes require an emergency reason")
    })?;
    let previous = provider_by_id(&state, id).await?;
    let policy_decision = json!({
        "decision": "allowed",
        "gate": "provider_lifecycle_emergency",
        "emergency": true,
        "reason": reason,
        "previous_status": previous.status,
        "requested_status": status,
    });
    let provider = state.update_provider_status(id, &status).await?;
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "provider.status_updated",
            "provider",
            Some(id),
            json!({
                "subject": principal.subject_id,
                "provider_name": provider.name,
                "status": provider.status,
                "policy_decision": policy_decision
            }),
        ))
        .await?;
    Ok(Json(provider))
}

async fn request_provider_status_approval(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<RequestProviderStatusApproval>,
) -> Result<Json<ProviderStatusApprovalResponse>, AppError> {
    let principal = principal_from_request(&state, &headers).await?;
    let request = AuthorizationRequest {
        tenant_id: state.current_tenant_id(),
        permission: Permission::Admin,
        resource_type: "provider".to_string(),
        resource_id: Some(id),
    };
    state.authorizer.authorize(&principal, &request).await?;
    enforce_resource_scope(&state, &principal, &request).await?;
    let requested_status = normalize_provider_status(&input.status)?;
    let provider = provider_by_id(&state, id).await?;
    if provider.status == requested_status {
        return Err(AppError::bad_request(
            "provider already has requested status",
        ));
    }
    if provider
        .config
        .get("pending_status_approval")
        .and_then(|approval| approval.get("status"))
        .and_then(Value::as_str)
        == Some("pending")
    {
        return Err(AppError::bad_request(
            "provider already has a pending status approval",
        ));
    }
    let requested_at = Utc::now();
    let approval = json!({
        "id": Uuid::new_v4(),
        "status": "pending",
        "provider_id": provider.id,
        "provider_name": provider.name,
        "previous_status": provider.status,
        "requested_status": requested_status,
        "requested_by": principal.subject_id,
        "reason": optional_trimmed(input.reason.as_deref()),
        "approver_subject": optional_trimmed(input.approver_subject.as_deref()),
        "requested_at": requested_at,
    });
    let mut config = provider.config.as_object().cloned().unwrap_or_default();
    config.insert("pending_status_approval".to_string(), approval.clone());
    let updated = state
        .update_provider_config(id, Value::Object(config))
        .await?;
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "provider.status_approval_requested",
            "provider",
            Some(id),
            json!({
                "subject": principal.subject_id,
                "provider_name": provider.name,
                "previous_status": provider.status,
                "requested_status": requested_status,
                "approval": approval
            }),
        ))
        .await?;
    Ok(Json(ProviderStatusApprovalResponse {
        provider: updated,
        approval,
    }))
}

async fn approve_provider_status_approval(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<DecideProviderStatusApproval>,
) -> Result<Json<ProviderStatusApprovalResponse>, AppError> {
    decide_provider_status_approval(state, id, headers, "approved", input.comment).await
}

async fn reject_provider_status_approval(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<DecideProviderStatusApproval>,
) -> Result<Json<ProviderStatusApprovalResponse>, AppError> {
    decide_provider_status_approval(state, id, headers, "rejected", input.comment).await
}

async fn decide_provider_status_approval(
    state: AppState,
    id: Uuid,
    headers: HeaderMap,
    decision: &str,
    comment: Option<String>,
) -> Result<Json<ProviderStatusApprovalResponse>, AppError> {
    let principal = principal_from_request(&state, &headers).await?;
    let request = AuthorizationRequest {
        tenant_id: state.current_tenant_id(),
        permission: Permission::Admin,
        resource_type: "provider".to_string(),
        resource_id: Some(id),
    };
    state.authorizer.authorize(&principal, &request).await?;
    enforce_resource_scope(&state, &principal, &request).await?;
    let provider = provider_by_id(&state, id).await?;
    let mut approval = provider
        .config
        .get("pending_status_approval")
        .cloned()
        .ok_or_else(|| AppError::bad_request("provider has no pending status approval"))?;
    if approval.get("status").and_then(Value::as_str) != Some("pending") {
        return Err(AppError::bad_request(
            "provider status approval is not pending",
        ));
    }
    let requested_by = approval
        .get("requested_by")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if requested_by == principal.subject_id {
        return Err(AppError::forbidden(
            "provider status approval requires a different approver",
        ));
    }
    if let Some(approver_subject) = approval
        .get("approver_subject")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if approver_subject != principal.subject_id {
            return Err(AppError::forbidden(format!(
                "provider status approval is delegated to {approver_subject}"
            )));
        }
    }
    let decided_at = Utc::now();
    approval["status"] = json!(decision);
    approval["decided_by"] = json!(principal.subject_id.clone());
    approval["decided_at"] = json!(decided_at);
    approval["comment"] = json!(optional_trimmed(comment.as_deref()));
    let mut config = provider.config.as_object().cloned().unwrap_or_default();
    config.remove("pending_status_approval");
    config.insert("last_status_approval".to_string(), approval.clone());
    let updated = state
        .update_provider_config(id, Value::Object(config))
        .await?;
    let updated = if decision == "approved" {
        let requested_status = approval
            .get("requested_status")
            .and_then(Value::as_str)
            .ok_or_else(|| AppError::bad_request("pending approval missing requested_status"))?;
        state.update_provider_status(id, requested_status).await?
    } else {
        updated
    };
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            &format!("provider.status_approval_{decision}"),
            "provider",
            Some(id),
            json!({
                "subject": principal.subject_id,
                "provider_name": provider.name,
                "decision": decision,
                "approval": approval
            }),
        ))
        .await?;
    Ok(Json(ProviderStatusApprovalResponse {
        provider: updated,
        approval,
    }))
}

async fn provider_by_id(state: &AppState, id: Uuid) -> Result<ProviderRecord, AppError> {
    state
        .list_providers()
        .await?
        .into_iter()
        .find(|provider| provider.id == id)
        .ok_or_else(|| AppError::not_found("provider not found"))
}

async fn rotate_provider_api_key_ref(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(input): Json<RotateProviderApiKeyRef>,
) -> Result<Json<ProviderRecord>, AppError> {
    let principal = principal_from_request(&state, &headers).await?;
    let request = AuthorizationRequest {
        tenant_id: state.current_tenant_id(),
        permission: Permission::Admin,
        resource_type: "provider".to_string(),
        resource_id: Some(id),
    };
    state.authorizer.authorize(&principal, &request).await?;
    enforce_resource_scope(&state, &principal, &request).await?;
    let new_ref = normalize_provider_api_key_ref(&input.api_key_ref)?;
    let provider = state
        .list_providers()
        .await?
        .into_iter()
        .find(|provider| provider.id == id)
        .ok_or_else(|| AppError::not_found("provider not found"))?;
    let previous_ref = provider
        .config
        .get("api_key_ref")
        .and_then(Value::as_str)
        .map(ToString::to_string);
    let mut config = provider.config.as_object().cloned().unwrap_or_default();
    config.insert("api_key_ref".to_string(), Value::String(new_ref.clone()));
    config.remove("api_key_env");
    let updated = state
        .update_provider_config(id, Value::Object(config))
        .await?;
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "provider.api_key_ref_rotated",
            "provider",
            Some(id),
            json!({
                "subject": principal.subject_id,
                "provider_name": provider.name,
                "previous_api_key_ref": previous_ref,
                "new_api_key_ref": new_ref,
            }),
        ))
        .await?;
    Ok(Json(updated))
}

fn normalize_provider_status(status: &str) -> Result<String, AppError> {
    match status.trim() {
        "active" => Ok("active".to_string()),
        "disabled" => Ok("disabled".to_string()),
        "archived" => Ok("archived".to_string()),
        other => Err(AppError::bad_request(format!(
            "unsupported provider status: {other}"
        ))),
    }
}

fn normalize_provider_api_key_ref(value: &str) -> Result<String, AppError> {
    let trimmed = value.trim();
    let Some(reference) = trimmed.strip_prefix("vault:") else {
        return Err(AppError::bad_request(
            "provider api key ref must use vault:path#key",
        ));
    };
    let Some((path, key)) = reference.split_once('#') else {
        return Err(AppError::bad_request(
            "provider api key ref must use vault:path#key",
        ));
    };
    let secret_ref = SecretRef::new(path, key)?;
    Ok(format!("vault:{}#{}", secret_ref.path, secret_ref.key))
}

fn normalize_mcp_name(name: &str) -> Result<String, AppError> {
    let name = name.trim();
    if name.is_empty() {
        return Err(AppError::bad_request("MCP server name is required"));
    }
    Ok(name.to_string())
}

fn normalize_mcp_transport(transport: &str) -> Result<String, AppError> {
    let transport = transport.trim();
    if transport.is_empty() {
        return Err(AppError::bad_request("MCP server transport is required"));
    }
    Ok(transport.to_string())
}

fn normalize_mcp_status(status: &str) -> Result<String, AppError> {
    match status.trim() {
        "active" => Ok("active".to_string()),
        "disabled" => Ok("disabled".to_string()),
        "archived" => Ok("archived".to_string()),
        other => Err(AppError::bad_request(format!(
            "unsupported MCP server status: {other}"
        ))),
    }
}

fn normalize_mcp_tool_allowlist(tool_allowlist: Vec<String>) -> Result<Vec<String>, AppError> {
    let mut tools: Vec<_> = tool_allowlist
        .into_iter()
        .map(|tool| tool.trim().to_string())
        .filter(|tool| !tool.is_empty())
        .collect();
    tools.sort();
    tools.dedup();
    if tools.len() > 100 {
        return Err(AppError::bad_request(
            "MCP server tool allowlist cannot exceed 100 tools",
        ));
    }
    Ok(tools)
}

fn normalize_mcp_config(config: Value) -> Result<Value, AppError> {
    let mut map = config
        .as_object()
        .cloned()
        .ok_or_else(|| AppError::bad_request("MCP server config must be a JSON object"))?;
    let mut secret_refs = Vec::new();
    if let Some(secret_ref) = map.get("secret_ref").and_then(Value::as_str) {
        secret_refs.push(normalize_mcp_secret_ref(secret_ref)?);
    }
    if let Some(value) = map.get("secret_refs") {
        let refs = value.as_array().ok_or_else(|| {
            AppError::bad_request("MCP server config secret_refs must be an array")
        })?;
        for (index, item) in refs.iter().enumerate() {
            let Some(secret_ref) = item.as_str() else {
                return Err(AppError::bad_request(format!(
                    "MCP server config secret_refs[{index}] must be a string"
                )));
            };
            secret_refs.push(normalize_mcp_secret_ref(secret_ref)?);
        }
    }
    secret_refs.sort();
    secret_refs.dedup();
    if !secret_refs.is_empty() {
        map.insert("secret_refs".to_string(), json!(secret_refs));
        map.remove("secret_ref");
    }
    Ok(Value::Object(map))
}

fn normalize_mcp_secret_ref(value: &str) -> Result<String, AppError> {
    let trimmed = value.trim();
    let Some(reference) = trimmed.strip_prefix("vault:") else {
        return Err(AppError::bad_request(
            "MCP server secret refs must use vault:path#key",
        ));
    };
    let Some((path, key)) = reference.split_once('#') else {
        return Err(AppError::bad_request(
            "MCP server secret refs must use vault:path#key",
        ));
    };
    let secret_ref = SecretRef::new(path, key)?;
    Ok(format!("vault:{}#{}", secret_ref.path, secret_ref.key))
}

fn mcp_config_secret_refs(config: &Value) -> Vec<String> {
    config
        .get("secret_refs")
        .and_then(Value::as_array)
        .map(|refs| {
            refs.iter()
                .filter_map(Value::as_str)
                .map(ToString::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn mcp_secret_ref_from_stored_value(value: &str) -> Result<SecretRef, AppError> {
    let Some(reference) = value.trim().strip_prefix("vault:") else {
        return Err(AppError::bad_request(
            "MCP server secret refs must use vault:path#key",
        ));
    };
    let Some((path, key)) = reference.split_once('#') else {
        return Err(AppError::bad_request(
            "MCP server secret refs must use vault:path#key",
        ));
    };
    SecretRef::new(path, key)
}

pub(crate) async fn resolve_mcp_runtime_secret_refs(
    server: &McpServerRecord,
) -> Result<usize, AppError> {
    let refs = mcp_config_secret_refs(&server.config);
    if refs.is_empty() {
        return Ok(0);
    }
    let secret_provider = secret_provider_from_env().map_err(|error| {
        AppError::forbidden(format!(
            "MCP server {} secret ref could not be resolved: {}",
            server.name, error.message
        ))
    })?;
    let secret_config = SecretProviderConfig::from_env().map_err(|error| {
        AppError::forbidden(format!(
            "MCP server {} secret ref could not be resolved: {}",
            server.name, error.message
        ))
    })?;
    for value in &refs {
        let secret_ref = mcp_secret_ref_from_stored_value(value)?;
        secret_provider
            .read_secret(&secret_config, &secret_ref)
            .await
            .map_err(|error| {
                AppError::forbidden(format!(
                    "MCP server {} secret ref could not be resolved: {}",
                    server.name, error.message
                ))
            })?;
    }
    Ok(refs.len())
}

async fn get_provider_health(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
) -> Result<Json<ProviderHealth>, AppError> {
    let principal = principal_from_request(&state, &headers).await?;
    let request = AuthorizationRequest {
        tenant_id: state.current_tenant_id(),
        permission: Permission::Admin,
        resource_type: "provider".to_string(),
        resource_id: Some(id),
    };
    state.authorizer.authorize(&principal, &request).await?;
    enforce_resource_scope(&state, &principal, &request).await?;
    let provider = state
        .list_providers()
        .await?
        .into_iter()
        .find(|provider| provider.id == id)
        .ok_or_else(|| AppError::not_found("provider not found"))?;
    let health = provider_health(&provider).await;
    state
        .append_audit_log(new_audit_log(
            None,
            "user",
            None,
            "provider.health_checked",
            "provider",
            Some(provider.id),
            json!({
                "subject": principal.subject_id,
                "provider_name": provider.name,
                "healthy": health.healthy,
                "issues": health.issues,
                "checks": health.checks
            }),
        ))
        .await?;
    Ok(Json(health))
}

async fn provider_health(provider: &ProviderRecord) -> ProviderHealth {
    let secret_provider = secret_provider_from_env();
    let (secret_provider, secret_provider_error) = match secret_provider {
        Ok(secret_provider) => (Some(secret_provider), None),
        Err(error) => (None, Some(error.message)),
    };
    provider_health_from_lookup(
        provider,
        &|key| std::env::var(key).ok(),
        secret_provider.as_deref(),
        secret_provider_error,
    )
    .await
}

async fn provider_health_from_lookup<F>(
    provider: &ProviderRecord,
    lookup: &F,
    secret_provider: Option<&dyn SecretProvider>,
    secret_provider_error: Option<String>,
) -> ProviderHealth
where
    F: Fn(&str) -> Option<String>,
{
    let mut issues = Vec::new();
    let provider_type = provider.provider_type.trim().to_ascii_lowercase();
    if provider.status != "active" {
        issues.push(format!("provider status is {}", provider.status));
    }
    let has_base_url = provider
        .base_url
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty());
    let has_default_model = provider
        .default_model
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty());
    let api_key_env = provider
        .config
        .get("api_key_env")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty());
    let api_key_ref = provider
        .config
        .get("api_key_ref")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty());
    let api_key_env_present = api_key_env.is_some_and(|env_key| lookup(env_key).is_some());
    let mut api_key_ref_resolved = false;
    let mut external_probe = "not_applicable".to_string();
    let mut external_probe_status = Value::Null;

    match provider_type.as_str() {
        "mock" | "mock_openai_compatible" => {}
        "openai_compatible" | "openai-compatible" => {
            if !has_base_url {
                issues.push("openai-compatible provider requires base_url".to_string());
            }
            if api_key_env.is_none() && api_key_ref.is_none() {
                issues.push(
                    "openai-compatible provider requires config.api_key_env or config.api_key_ref"
                        .to_string(),
                );
            }
            if api_key_env.is_some() && !api_key_env_present {
                issues.push("configured api_key_env is not present in the environment".to_string());
            }
            let mut api_key_for_probe = None;
            if let Some(env_key) = api_key_env.filter(|_| api_key_env_present) {
                api_key_for_probe = lookup(env_key);
            } else if let Some(api_key_ref) = api_key_ref {
                match secret_provider {
                    Some(secret_provider) => {
                        match provider::provider_api_key_from_stored_value_with_lookup(
                            api_key_ref,
                            lookup,
                            secret_provider,
                        )
                        .await
                        {
                            Ok(api_key) => {
                                api_key_ref_resolved = true;
                                api_key_for_probe = Some(api_key);
                            }
                            Err(error) => {
                                external_probe = "failed_api_key_ref".to_string();
                                issues.push(format!(
                                    "configured api_key_ref could not be read: {}",
                                    error.message
                                ));
                            }
                        }
                    }
                    None => {
                        external_probe = "failed_api_key_ref".to_string();
                        issues.push(format!(
                            "configured api_key_ref could not be read: {}",
                            secret_provider_error
                                .as_deref()
                                .unwrap_or("secret provider is not configured")
                        ));
                    }
                }
            }
            if provider.status == "active" && has_base_url {
                if let Some(api_key) = api_key_for_probe {
                    let probe = probe_openai_compatible_provider(
                        provider.base_url.as_deref().unwrap_or_default(),
                        &api_key,
                    )
                    .await;
                    external_probe = probe.0;
                    external_probe_status = probe.1;
                    if let Some(issue) = probe.2 {
                        issues.push(issue);
                    }
                } else if external_probe == "not_applicable" {
                    external_probe = "skipped_configuration".to_string();
                }
            } else if provider.status != "active" {
                external_probe = "skipped_inactive".to_string();
            } else if !has_base_url || (!api_key_env_present && api_key_ref.is_none()) {
                external_probe = "skipped_configuration".to_string();
            }
        }
        other => issues.push(format!("provider type {other} is not supported")),
    }

    ProviderHealth {
        provider_id: provider.id,
        name: provider.name.clone(),
        status: provider.status.clone(),
        healthy: issues.is_empty(),
        issues,
        checks: json!({
            "provider_type": provider.provider_type,
            "has_base_url": has_base_url,
            "has_default_model": has_default_model,
            "has_api_key_env": api_key_env.is_some(),
            "api_key_env_present": api_key_env_present,
            "has_api_key_ref": api_key_ref.is_some(),
            "api_key_ref_resolved": api_key_ref_resolved,
            "external_probe": external_probe,
            "external_probe_status": external_probe_status,
        }),
        checked_at: Utc::now(),
    }
}

async fn probe_openai_compatible_provider(
    base_url: &str,
    api_key: &str,
) -> (String, Value, Option<String>) {
    let endpoint = format!("{}/v1/models", base_url.trim().trim_end_matches('/'));
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(5))
        .build()
    {
        Ok(client) => client,
        Err(error) => {
            return (
                "failed".to_string(),
                json!({"error": error.to_string()}),
                Some("provider health probe client could not be created".to_string()),
            );
        }
    };
    match client.get(&endpoint).bearer_auth(api_key).send().await {
        Ok(response) => {
            let status = response.status();
            if status.is_success() {
                (
                    "healthy".to_string(),
                    json!({"url": endpoint, "status": status.as_u16()}),
                    None,
                )
            } else {
                (
                    "failed".to_string(),
                    json!({"url": endpoint, "status": status.as_u16()}),
                    Some(format!(
                        "provider external health probe failed with status {status}"
                    )),
                )
            }
        }
        Err(error) => (
            "failed".to_string(),
            json!({"url": endpoint, "error": error.to_string()}),
            Some("provider external health probe failed".to_string()),
        ),
    }
}

