    #[tokio::test]
    async fn provider_health_resolves_vault_api_key_ref_for_external_probe() {
        let vault_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("vault listener");
        let vault_addr = vault_listener.local_addr().expect("vault addr");
        let vault = Router::new()
            .route("/v1/sys/health", get(mock_vault_health))
            .route("/v1/kv/data/providers/openai", get(mock_vault_provider_key));
        let vault_server = tokio::spawn(async move {
            axum::serve(vault_listener, vault)
                .await
                .expect("mock vault");
        });

        let provider_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("provider listener");
        let provider_addr = provider_listener.local_addr().expect("provider addr");
        let provider_probe = Router::new().route("/v1/models", get(mock_provider_models));
        let provider_server = tokio::spawn(async move {
            axum::serve(provider_listener, provider_probe)
                .await
                .expect("mock provider models");
        });

        let record = ProviderRecord {
            id: Uuid::new_v4(),
            provider_type: "openai-compatible".to_string(),
            name: "vault-probed-openai-compatible".to_string(),
            base_url: Some(format!("http://{provider_addr}")),
            default_model: Some("gpt-5.4-mini".to_string()),
            config: json!({"api_key_ref": "vault:providers/openai#api_key"}),
            status: "active".to_string(),
            created_at: Utc::now(),
        };
        let lookup = |key: &str| match key {
            "MANDOFORGE_SECRET_PROVIDER" => Some("vault".to_string()),
            "MANDOFORGE_VAULT_ADDR" => Some(format!("http://{vault_addr}")),
            "MANDOFORGE_VAULT_MOUNT" => Some("kv".to_string()),
            "MANDOFORGE_VAULT_TOKEN" => Some("test-vault-token".to_string()),
            _ => None,
        };
        let secret_provider = VaultSecretProvider::new().expect("vault provider");
        let health =
            provider_health_from_lookup(&record, &lookup, Some(&secret_provider), None).await;

        assert!(health.healthy);
        assert!(health.issues.is_empty());
        assert_eq!(health.checks["has_api_key_ref"], true);
        assert_eq!(health.checks["api_key_ref_resolved"], true);
        assert_eq!(health.checks["external_probe"], "healthy");
        assert_eq!(health.checks["external_probe_status"]["status"], 200);

        vault_server.abort();
        provider_server.abort();
    }

    #[tokio::test]
    async fn vault_readiness_reports_secret_consumers_and_kms_gate() {
        let app = test_app().await;
        let organization: Organization = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/organizations")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({"name": "Vault Readiness Org", "slug": "vault-readiness-org"})
                        .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        let team: Team = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/organizations/{}/teams", organization.id))
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({"name": "Vault Readiness Team", "slug": "vault-readiness-team"})
                        .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        let _: SecretRecord = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/vault/secrets")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "name": "registered-openai",
                        "path": "providers/openai",
                        "key": "api_key",
                        "scope_type": "team",
                        "scope_id": team.id
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        let provider: ProviderRecord = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/providers")
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "provider_type": "openai_compatible",
                        "name": "ready-openai",
                        "base_url": "https://provider.example.invalid",
                        "default_model": "gpt-5.4-mini",
                        "config": {"api_key_ref": "vault:providers/openai#api_key"}
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;
        let _: McpServerRecord = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri(format!("/api/teams/{}/mcp-servers", team.id))
                .header("content-type", "application/json")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::from(
                    json!({
                        "name": "readiness-docs",
                        "transport": "http",
                        "tool_allowlist": ["search"],
                        "config": {"secret_refs": ["vault:mcp/docs#api_key"]}
                    })
                    .to_string(),
                ))
                .expect("valid request"),
        )
        .await;

        let report: VaultReadinessReport = request_json(
            app.clone(),
            Request::builder()
                .uri("/api/vault/readiness")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;

        assert_eq!(report.status, "failed");
        assert_eq!(report.secret_record_count, 1);
        assert_eq!(report.active_secret_record_count, 1);
        assert_eq!(report.provider_ref_count, 1);
        assert_eq!(report.mcp_secret_ref_count, 1);
        assert_eq!(report.unresolved_ref_count, 1);
        assert_eq!(report.kms.status, "reserved");
        assert!(!report.kms.endpoint_configured);
        assert_eq!(report.kms.validation_mode, "health-check");
        assert_eq!(report.production_rotation.status, "blocked");
        assert!(report.production_rotation.production_blocked);
        assert!(!report.production_rotation.vault_healthy);
        assert!(!report.production_rotation.kms_ready);
        assert!(!report.production_rotation.unresolved_refs_clear);
        assert!(report.production_rotation.stale_rotations_clear);
        assert!(!report.production_rotation.latest_rotation_validated);
        assert!(report.checks.iter().any(|check| {
            check.resource_type == "provider"
                && check.resource_id == Some(provider.id)
                && check.status == "passed"
        }));
        assert!(report.attention_items.iter().any(|item| {
            item.resource_type == "mcp_server" && item.message.contains("vault:mcp/docs#api_key")
        }));
        assert!(report.attention_items.iter().any(|item| {
            item.resource_type == "kms"
                && item
                    .message
                    .contains("external KMS/HSM provider is not configured")
        }));
        assert!(report.attention_items.iter().any(|item| {
            item.resource_type == "kms"
                && item
                    .message
                    .contains("MANDOFORGE_KMS_ENDPOINT is not configured")
        }));
        assert!(report.attention_items.iter().any(|item| {
            item.kind == "production_rotation_blocked" && item.severity == "critical"
        }));
        let rotation_run: VaultKmsRotationRun = request_json(
            app.clone(),
            Request::builder()
                .method("POST")
                .uri("/api/vault/kms/rotation/run")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert_eq!(rotation_run.status, "blocked");
        assert_eq!(rotation_run.kms_status, "reserved");
        assert_eq!(rotation_run.blocked_count, 2);
        assert!(
            rotation_run
                .actions
                .iter()
                .any(|action| action == "configure_external_kms_or_hsm")
        );
        let audit_logs: Vec<AuditLog> = request_json(
            app,
            Request::builder()
                .uri("/api/audit-logs")
                .header("x-mandoforge-subject", "admin-1")
                .header("x-mandoforge-roles", "admin")
                .body(Body::empty())
                .expect("valid request"),
        )
        .await;
        assert!(audit_logs.iter().any(|log| {
            log.action == "vault.kms_rotation_run" && log.details["status"] == "blocked"
        }));
    }

