        let agent_shim_path = shim_dir.join("agent-coder");
        fs::write(
            &env_shim_path,
            "#!/usr/bin/env bash\nset -euo pipefail\necho \"source=environment\"\necho \"profile=$MANDOFORGE_AGENT_CLI_PROFILE\"\necho \"task=$MANDOFORGE_AGENT_TASK\"\necho \"argv=$*\"\n",
        )
