    fn ai_governance_update_manifest_path_string(version: &str) -> String {
        let source_dir = ai_governance_pack_dir();
        let target_dir = test_workspace_root()
            .join("workflow-pack-updates")
            .join(Uuid::new_v4().to_string());
        copy_dir_all(&source_dir, &target_dir).expect("copy workflow pack fixture");
        let manifest_path = target_dir.join("package.yaml");
        let manifest = std::fs::read_to_string(&manifest_path).expect("read copied manifest");
        std::fs::write(
            &manifest_path,
            manifest.replacen("version: 0.1.0", &format!("version: {version}"), 1),
        )
        .expect("write updated manifest");
        std::fs::canonicalize(manifest_path)
            .expect("updated manifest exists")
            .display()
            .to_string()
    }

    fn copy_dir_all(source: &Path, target: &Path) -> std::io::Result<()> {
        std::fs::create_dir_all(target)?;
        for entry in std::fs::read_dir(source)? {
            let entry = entry?;
            let ty = entry.file_type()?;
            let target_path = target.join(entry.file_name());
            if ty.is_dir() {
                copy_dir_all(&entry.path(), &target_path)?;
            } else {
                std::fs::copy(entry.path(), target_path)?;
            }
        }
        Ok(())
    }

    async fn request_json<T: for<'de> Deserialize<'de>>(app: Router, request: Request<Body>) -> T {
        let response = app.oneshot(request).await.expect("request succeeds");
        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("read response body");
        serde_json::from_slice(&body).expect("json response")
    }

    async fn request_value(app: Router, request: Request<Body>) -> (StatusCode, Value) {
        let response = app.oneshot(request).await.expect("request succeeds");
        let status = response.status();
        let body = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("read response body");
        let value = serde_json::from_slice(&body).unwrap_or_else(|_| json!({}));
        (status, value)
    }

    async fn request_sse_until_contains(
        app: Router,
        request: Request<Body>,
        needles: &[&str],
    ) -> (StatusCode, String) {
        let response = app.oneshot(request).await.expect("request succeeds");
        let status = response.status();
        let body = sse_response_until_contains(response, needles).await;
        (status, body)
    }

    async fn sse_response_until_contains(response: Response, needles: &[&str]) -> String {
        let mut stream = response.into_body().into_data_stream();
        let mut body = String::new();
        let deadline = tokio::time::sleep(Duration::from_secs(2));
        tokio::pin!(deadline);
        loop {
            if needles.iter().all(|needle| body.contains(needle)) {
                return body;
            }
            tokio::select! {
                chunk = stream.next() => {
                    let Some(chunk) = chunk else {
                        return body;
                    };
                    let chunk = chunk.expect("read sse chunk");
                    body.push_str(&String::from_utf8_lossy(&chunk));
                }
                _ = &mut deadline => {
                    return body;
                }
            }
        }
    }

    fn json_request(method: &str, uri: &str, body: Value) -> Request<Body> {
        Request::builder()
            .method(method)
            .uri(uri)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("valid request")
    }

    fn json_request_with_headers(
        method: &str,
        uri: &str,
        body: Value,
        headers: &[(&str, &str)],
    ) -> Request<Body> {
        let mut builder = Request::builder()
            .method(method)
            .uri(uri)
            .header("content-type", "application/json");
        for (name, value) in headers {
            builder = builder.header(*name, *value);
        }
        builder
            .body(Body::from(body.to_string()))
            .expect("valid request")
    }

